/****************************************************************************
 * app/audio_test/main.c
 *
 * SF32LB52 /dev/audio/audio0 音频通路测试 + 验收测试
 *
 * 用法:
 *   audio_test                          播放 1kHz 1 秒
 *   audio_test <ms> [freq]              播放正弦
 *   audio_test record [ms] [file]       录音（给 file 则存成裸 PCM: 16k mono s16le）
 *   audio_test playfile <file>          回放裸 PCM 文件
 *   audio_test loop [n]                 连续 open/config/start/stop/close n 次
 *   audio_test stopwait [ms]            录音 read 阻塞中从另一个任务发 STOP，看能否退出
 *   audio_test vol <0..1000>            设音量/录音增益
 *   audio_test audfix                     ⚠️ 诊断期临时：手动打一次 RX 恢复
 *                                         （复位整块 DMAC1 + 重建三个通道句柄）
 *
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/audio/audio.h>
#include <nuttx/sched.h>

#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define AUDIO_DEV      "/dev/audio/audio0"
#define SAMPLE_RATE    16000
#define CHANNELS       1
#define BITS           16

/* ⚠️ 诊断期临时的板级入口（定义在 board/contest_board/src/sf32lb52_audio.c）。
 * 板级头文件本轮不许改（sf32lb52_audio_in.h 那边另一个任务在用），所以原型在
 * 这里临时声明一份；删掉 audfix 分支时记得连它一起删。
 *
 * 参数：1..5 = 只打那一级；<=0 = 依次打 L1→L2→L3（L4 拆会话、L5 复位整块
 *       DMAC1，两级都要明说）。
 * 返回：>0 = 实际打的级（"依次"模式＝第一个让通路动起来的级）；0 = 都没动起来；
 *       -ENODEV = 音频驱动还没起来；-EINVAL = 级号越界。 */

int sf32lb52_audio_rx_fix(int level);

/* stopwait 用：录音任务的状态 */
static volatile int     g_rd_done;
static volatile ssize_t g_rd_n;
static int              g_rd_fd;
static FAR int16_t     *g_rd_buf;
static int              g_rd_len;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int gen_sine(FAR int16_t *buf, int nsamples, int freq)
{
  int i;

  for (i = 0; i < nsamples; i++)
    {
      /* 幅度 0.2（约 -14dBFS）：原来 0.5 太吵，测试时刺耳 */
      buf[i] = (int16_t)(32767.0 * 0.2 *
               sin(2.0 * M_PI * freq * (double)i / SAMPLE_RATE));
    }

  return nsamples;
}

static void print_caps(int fd)
{
  struct audio_caps_s caps;
  int ret;

  memset(&caps, 0, sizeof(caps));
  caps.ac_len     = sizeof(caps);
  caps.ac_type    = AUDIO_TYPE_QUERY;
  caps.ac_subtype = AUDIO_TYPE_QUERY;

  ret = ioctl(fd, AUDIOIOC_GETCAPS, (unsigned long)&caps);
  printf("GETCAPS ret=%d type=0x%02x fmt=0x%08lx\n",
         ret, caps.ac_controls.b[0],
         (unsigned long)caps.ac_format.hw);
}

static int configure_path(int fd, bool record)
{
  struct audio_caps_desc_s capdesc;
  int ret;

  memset(&capdesc, 0, sizeof(capdesc));
  capdesc.caps.ac_len      = sizeof(struct audio_caps_s);
  capdesc.caps.ac_type     = record ? AUDIO_TYPE_INPUT : AUDIO_TYPE_OUTPUT;
  capdesc.caps.ac_channels = CHANNELS;
  capdesc.caps.ac_controls.hw[0] = SAMPLE_RATE;
  capdesc.caps.ac_controls.b[2]  = BITS;

  ret = ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&capdesc);
  printf("CONFIGURE ret=%d (%dHz %dch %dbit%s)\n",
         ret, SAMPLE_RATE, CHANNELS, BITS, record ? " input" : "");
  return ret;
}

/* 打开 -> 配置 -> START，成功返回 0 */
static int start_path(bool record, FAR int *fdp)
{
  int fd;
  int ret;

  fd = open(AUDIO_DEV, record ? O_RDONLY : O_WRONLY);
  if (fd < 0)
    {
      printf("open %s failed: %d\n", AUDIO_DEV, fd);
      return -1;
    }

  print_caps(fd);

  ret = configure_path(fd, record);
  if (ret < 0)
    {
      close(fd);
      return -1;
    }

  ret = ioctl(fd, AUDIOIOC_START, 0);
  printf("START ret=%d\n", ret);
  if (ret < 0)
    {
      close(fd);
      return -1;
    }

  *fdp = fd;
  return 0;
}

static void stop_path(int fd)
{
  ioctl(fd, AUDIOIOC_STOP, 0);
  printf("STOP done\n");
  close(fd);
}

/* 统计 peak/avg，判断是否真的有声音 */
static void report_level(FAR const int16_t *buf, int nsamples)
{
  int i;
  int peak = 0;
  long sum = 0;

  for (i = 0; i < nsamples; i++)
    {
      int v = buf[i];

      if (v < 0)
        {
          v = -v;
        }

      if (v > peak)
        {
          peak = v;
        }

      sum += v;
    }

  printf("RECORD peak=%d avg=%ld (16k mono 16bit)\n",
         peak, nsamples > 0 ? sum / nsamples : 0);
  printf("RECORD %s\n", peak > 500 ? "OK: 检测到声音" :
         "静音: 麦克风无信号或通路未通");
}

/* 录音任务：read 会一直阻塞到读满 */
static int record_reader(int argc, FAR char *argv[])
{
  g_rd_n    = read(g_rd_fd, g_rd_buf, g_rd_len);
  g_rd_done = 1;
  return 0;
}

/****************************************************************************
 * 验收测试 1：录 N 毫秒 -> 存文件 -> 回放
 ****************************************************************************/

static int do_record(int duration_ms, FAR const char *file)
{
  int nsamples = SAMPLE_RATE * duration_ms / 1000;
  FAR int16_t *buf;
  int fd;
  ssize_t n;

  printf("audio_test: record %dms%s%s\n", duration_ms,
         file ? " -> " : "", file ? file : "");

  buf = (FAR int16_t *)malloc(nsamples * sizeof(int16_t));
  if (buf == NULL)
    {
      printf("malloc failed\n");
      return 1;
    }

  if (start_path(true, &fd) < 0)
    {
      free(buf);
      return 1;
    }

  n = read(fd, buf, nsamples * sizeof(int16_t));
  printf("READ done: %zd of %d bytes\n", n, nsamples * 2);
  report_level(buf, nsamples);
  stop_path(fd);

  if (file != NULL && n > 0)
    {
      FILE *fp = fopen(file, "wb");

      if (fp == NULL)
        {
          printf("open %s for write failed\n", file);
        }
      else
        {
          size_t w = fwrite(buf, 1, n, fp);

          fclose(fp);
          printf("SAVED %zu bytes -> %s\n", w, file);
        }
    }

  free(buf);
  return 0;
}

/****************************************************************************
 * 验收测试：回放裸 PCM 文件
 ****************************************************************************/

static int do_playfile(FAR const char *file)
{
  FAR int16_t *buf;
  long size;
  int nsamples;
  int fd;
  ssize_t n;
  FILE *fp;

  fp = fopen(file, "rb");
  if (fp == NULL)
    {
      printf("open %s failed\n", file);
      return 1;
    }

  fseek(fp, 0, SEEK_END);
  size = ftell(fp);
  fseek(fp, 0, SEEK_SET);

  buf = (FAR int16_t *)malloc(size);
  if (buf == NULL)
    {
      printf("malloc %ld failed\n", size);
      fclose(fp);
      return 1;
    }

  n = fread(buf, 1, size, fp);
  fclose(fp);
  nsamples = n / 2;

  printf("audio_test: playfile %s (%ld bytes, %d ms)\n",
         file, (long)n, nsamples * 1000 / SAMPLE_RATE);

  if (start_path(false, &fd) < 0)
    {
      free(buf);
      return 1;
    }

  n = write(fd, buf, nsamples * 2);
  printf("WRITE done: %zd of %d bytes\n", n, nsamples * 2);
  stop_path(fd);

  free(buf);
  return 0;
}

/****************************************************************************
 * 验收测试 2：连续启动/停止 n 次，验证还能再次打开
 ****************************************************************************/

static int do_loop(int count)
{
  int i;
  int ok = 0;
  int nsamples = SAMPLE_RATE * 200 / 1000;   /* 每次 200ms */
  FAR int16_t *buf;
  int fd;
  ssize_t n;

  printf("audio_test: loop %d times (200ms each)\n", count);

  buf = (FAR int16_t *)malloc(nsamples * sizeof(int16_t));
  if (buf == NULL)
    {
      printf("malloc failed\n");
      return 1;
    }

  gen_sine(buf, nsamples, 1000);

  for (i = 1; i <= count; i++)
    {
      printf("--- round %d/%d ---\n", i, count);

      if (start_path(false, &fd) < 0)
        {
          printf("ROUND %d FAILED: 打不开了\n", i);
          break;
        }

      n = write(fd, buf, nsamples * 2);
      printf("WRITE done: %zd of %d bytes\n", n, nsamples * 2);
      stop_path(fd);
      ok++;
    }

  printf("LOOP RESULT: %d/%d 轮成功\n", ok, count);
  free(buf);
  return ok == count ? 0 : 1;
}

/****************************************************************************
 * 验收测试 3：录音 read 阻塞中发 STOP，看线程能否退出
 ****************************************************************************/

static int do_stopwait(int wait_ms)
{
  int nsamples = SAMPLE_RATE * 3;       /* 要读 3 秒，故意读不满 */
  FAR int16_t *buf;
  int fd;
  int i;

  printf("audio_test: stopwait %dms (read 目标是 3 秒，中途发 STOP)\n",
         wait_ms);

  buf = (FAR int16_t *)malloc(nsamples * sizeof(int16_t));
  if (buf == NULL)
    {
      printf("malloc failed\n");
      return 1;
    }

  memset(buf, 0, nsamples * sizeof(int16_t));

  if (start_path(true, &fd) < 0)
    {
      free(buf);
      return 1;
    }

  g_rd_fd   = fd;
  g_rd_buf  = buf;
  g_rd_len  = nsamples * 2;
  g_rd_done = 0;
  g_rd_n    = -999;

  if (task_create("aud_rd", 100, 4096, record_reader, NULL) < 0)
    {
      printf("task_create failed\n");
      free(buf);
      stop_path(fd);
      return 1;
    }

  usleep(wait_ms * 1000);

  printf("read 还在阻塞中，现在发 STOP ...\n");
  ioctl(fd, AUDIOIOC_STOP, 0);
  printf("STOP 已发出\n");

  for (i = 0; i < 30 && !g_rd_done; i++)
    {
      usleep(100 * 1000);
    }

  if (g_rd_done)
    {
      printf("STOPWAIT OK: read 返回了 (n=%zd)，线程能退出\n", g_rd_n);
    }
  else
    {
      printf("STOPWAIT FAIL: STOP 之后 3 秒 read 仍未返回，线程卡住\n");
    }

  close(fd);
  free(buf);
  return g_rd_done ? 0 : 1;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  /* 验收测试模式 */
  if (argc > 1 && strcmp(argv[1], "record") == 0)
    {
      int        ms   = (argc > 2) ? atoi(argv[2]) : 1000;
      FAR const char *f = (argc > 3) ? argv[3] : NULL;

      return do_record(ms, f);
    }

  if (argc > 1 && strcmp(argv[1], "playfile") == 0)
    {
      if (argc < 3)
        {
          printf("用法: audio_test playfile <file>\n");
          return 1;
        }

      return do_playfile(argv[2]);
    }

  if (argc > 1 && strcmp(argv[1], "loop") == 0)
    {
      return do_loop((argc > 2) ? atoi(argv[2]) : 5);
    }

  if (argc > 1 && strcmp(argv[1], "stopwait") == 0)
    {
      return do_stopwait((argc > 2) ? atoi(argv[2]) : 1000);
    }

  /* 标准音量接口：AUDIOIOC_SETPARAMTER + AUDIO_TYPE_FEATURE + AUDIO_FU_VOLUME
   * 用法: audio_test vol <0..1000>     (0=-36dB 最小, 1000=+6dB 最大)
   * 播放时改 DAC 音量；录音时改麦克风数字增益。 */

  if (argc > 1 && strcmp(argv[1], "vol") == 0)
    {
      struct audio_caps_desc_s capdesc;
      int vol  = (argc > 2) ? atoi(argv[2]) : 500;
      int vret;
      int fd  = open(AUDIO_DEV, O_WRONLY);

      if (fd < 0)
        {
          printf("open %s failed: %d\n", AUDIO_DEV, fd);
          return 1;
        }

      memset(&capdesc, 0, sizeof(capdesc));
      capdesc.caps.ac_len          = sizeof(struct audio_caps_s);
      capdesc.caps.ac_type         = AUDIO_TYPE_FEATURE;
      capdesc.caps.ac_format.hw    = AUDIO_FU_VOLUME;
      capdesc.caps.ac_controls.hw[0] = (uint16_t)vol;

      vret = ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&capdesc);
      printf("SETVOLUME %d/1000 ret=%d\n", vol, vret);
      close(fd);
      return 0;
    }

  /* ⚠️ 诊断期临时：手动打一次 RX 恢复（就是复位整块 DMAC1 + 重建三个通道句柄，
   * 定案与依据见 sf32lb52_audio.c 顶部那一段）。
   * 用法: audio_test audfix
   *   不给参数、给 1、给 all 都是打这一记（参数只为兼容老用法保留）。
   * 它回答"这一记能不能把请求线叫活"，定案后本分支随驱动里那个动作一起删。
   *
   * 为什么直接调板级函数而不是走 ioctl：驱动这一轮不许改板级头文件
   * （sf32lb52_audio_in.h 那边另一个任务在用），所以原型只能在本文件里声明一份;
   * driver 里那个函数就是给这个入口用的（app 调板级符号是本板既有做法，
   * 例如 hello_app 直接调 sf32lb52_audio_rx_stats()）。 */

  if (argc > 1 && strcmp(argv[1], "audfix") == 0)
    {
      int level = (argc > 2 && strcmp(argv[2], "all") != 0) ? atoi(argv[2]) : 0;
      int ret   = sf32lb52_audio_rx_fix(level);

      if (ret < 0)
        {
          printf("audfix: 失败 ret=%d（-19=驱动还没起来, -22=参数不认识）\n",
                 ret);
          return 1;
        }

      printf("audfix: 打了那一记（看串口那行 RX 恢复，再等一次 read 的"
             "效果检查；正在播放时会被挡下，那行里是 note=skip-playback）\n");
      return 0;
    }

  /* 原来两种模式：播放正弦 */
  {
    int duration_ms = 1000;
    int freq        = 1000;
    int nsamples;
    FAR int16_t *buf;
    int fd;
    ssize_t n;

    if (argc > 1)
      {
        duration_ms = atoi(argv[1]);
      }

    if (argc > 2)
      {
        freq = atoi(argv[2]);
      }

    nsamples = SAMPLE_RATE * duration_ms / 1000;

    printf("audio_test: play %dHz %dms via %s\n", freq, duration_ms,
           AUDIO_DEV);

    buf = (FAR int16_t *)malloc(nsamples * sizeof(int16_t));
    if (buf == NULL)
      {
        printf("malloc failed\n");
        return 1;
      }

    gen_sine(buf, nsamples, freq);

    if (start_path(false, &fd) < 0)
      {
        free(buf);
        return 1;
      }

    n = write(fd, buf, nsamples * sizeof(int16_t));
    printf("WRITE done: %zd of %d bytes\n", n, nsamples * 2);
    stop_path(fd);

    free(buf);
  }

  printf("audio_test: done\n");
  return 0;
}

  /* ADC 模拟通路就在这一行真正开了：如实置位。
   * 注意它**不分方向**（原来的行为就是这样）：录音要用它，播放时也跟着使能、
   * 只是数据不经过它。删除它要另外验证，不在本次改动范围里。 */

  sf32lb52_audio_path_bit(&priv->adc_path_on, true, "adc_path_on",
                          "hw_start 开 ADC 模拟通路");

  /* codec：DAC 模拟通路 + 功放 —— 只有播放才碰。
   *
   * 纯录音时打开 DAC/功放是白开：麦克风数据不经过它，但功放使能那一下会在
   * 喇叭上打出一声可听见的爆音（实测 hw_test audio 这种纯录音也能听到）。
   *
   * 播放时的顺序也不能反（SF32LB52X 无独立 HP 块，主 Instance 使能 DAC）：
   *   1. 先把模拟通路以最小音量开起来，等耦合电容充到静态电平；
   *   2. 再开功放 —— 此时 DAC 输出没有跳变；
   *   3. 最后把音量拉到目标值。
   */

  if (playback)
    {
      __HAL_AUDCODEC_DAC_ENABLE(codec);
      HAL_AUDCODEC_Config_DACPath(codec, 1);
      HAL_AUDCODEC_Config_Analog_DACPath(codec->Init.dac_cfg.dac_clk);
      HAL_AUDCODEC_Config_DACPath(codec, 0);

      /* DAC 模拟通路开完就置位：收尾时只按这个位决定要不要关它 */

      sf32lb52_audio_path_bit(&priv->dac_path_on, true, "dac_path_on",
                              "hw_start 开 DAC 模拟通路");

      HAL_AUDCODEC_Config_DACPath_Volume(codec, 0, SF32LB52_AUDIO_VOL_MUTE);
      HAL_AUDCODEC_Config_DACPath_Volume(codec, 1, SF32LB52_AUDIO_VOL_MUTE);
      up_mdelay(SF32LB52_AUDIO_SETTLE_MS);

      sf32lb52_audio_pa_enable(true);

      /* 功放使能这一下也如实记：hw_stop/hw_shutdown 只有 pa_on 为真才去关它 */

      sf32lb52_audio_path_bit(&priv->pa_on, true, "pa_on",
                              "hw_start 开功放");

      up_mdelay(20);   /* 等功放上电稳定 */

      HAL_AUDCODEC_Config_DACPath_Volume(codec, 0, priv->playback_db);
      HAL_AUDCODEC_Config_DACPath_Volume(codec, 1, priv->playback_db);

      audinfo("DAC+PA path started\n");
    }
  else
    {
      audinfo("ADC path started (record only, DAC/PA untouched)\n");
    }

  /* 到这里硬件都真起来了，才把方向"提交"为当前会话的方向。
   * 在 START 成功这一刻提交（而不是 CONFIGURE 那一刻写）是本文件的关键约定：
   * 只 CONFIGURE、没 START 的调用（ai_audio.c 的 audio_hw_set_volume() 就是）
   * 必须**不改变**任何真实通路状态和当前会话方向，否则它会替正在录音的会话
   * 把方向翻成播放。pending_playback 只表示"下一次 START 想要的方向"。 */

  priv->playback = playback;
  priv->running  = true;

  /* 记下这次会话的持有者（谁把它起起来的），并清掉上一条会话留下的
   * "最近读写的线程" —— 新会话这会儿一个字节都还没读/写。
   * 这三个 id 就是 sf32lb52_audio_start() 判"方向冲突是别人真在用还是残留"
   * 的全部依据（见 struct 里那段说明与 sf32lb52_audio_holder_alive）。 */

  priv->holder_tid = nxsched_gettid();
  priv->holder_pid = getpid();
  priv->user_tid   = (pid_t)-1;

  /* 记下这条会话是"什么时候起的"：会话开头那一小段（真正读/写数据的线程还没进
   * 第一次调用）是唯一会"两条线程证据都查不到"的窗口，sf32lb52_audio_start()
   * 靠它判宽限期，绝不在这段时间里把一条刚起来的活会话当残局强停
   * （见 SF32LB52_AUDIO_SWITCH_GRACE_MS）。 */

  priv->holder_since = clock_systime_ticks();

  /* 新会话开始：上一次会话遗留的 read()（如果有）到此作废 —— 它的会话代号
   * 已经对不上，醒来就会自己退出，不会把新会话的数据接走。 */

  priv->session_gen++;

  /* 本会话的 arm 计数从 1 重新数（read 里每次"确认武装成功"自增；日志用它回答
   * "这一次失败落在本会话的第几帧"）。会话闸 rx_arm_gen 已经在上面那段 RX
   * 初始化里清成 0（= 闸门关着，等本会话第一次 read 武装成功才开）。 */

  priv->rx_arm_session = 0;

  /* 健康指纹也是"每会话第一条成功 read"才打一行，所以会话起点把它清掉
   * （见 struct 里 rx_health_done 的说明）。 */

  priv->rx_health_done = false;

  /* 这一行是"hw_start 到底有没有跑"的唯一凭据：
   *   有它 → ADC 模拟通路 / AUDPRC 真使能过，收不到数据要去查中断和数据通路；
   *   没有 → 上层 START 根本没执行到这里（多半被残留 running 的早退挡掉了），
   *          read() 等 DMA 超时（-110）就是从这个洞进来的。 */

  syslog(LOG_INFO, "AUDIO: hw_start 真跑了：playback=%d\n", (int)playback);
  return OK;
}

/****************************************************************************
 * Name: sf32lb52_audio_hw_stop
 *
 * Description: 停止播放/录音，关闭通路和功放
 *
 ****************************************************************************/

static int sf32lb52_audio_hw_stop(FAR struct sf32lb52_audio_s *priv)
{
  /* 幂等：已经停干净就不要再关一遍。
   *
   * 最后一个 fd 被 close() 时，上层 shutdown() 会紧跟在上层的
   * AUDIOIOC_STOP 之后进来，重复关一次已经关掉的模拟通路会卡死
   * （见 sf32lb52_audio_hw_shutdown 的注释）。
   * 判据里除了 running 还要看 rx_busy/rx_aborted/rx_apb/tx_apb：
   * 这些都是"还没收尾"的状态，有一样没清就走完整流程，别漏掉 buffer。
   *
   * 三个真实通路位也必须进判据 —— 原来那五项的判据在新位参与后**不再成立**：
   * hw_shutdown() 是故意不关模拟通路的（关中断上下文里关模拟级会卡死），
   * 它只清 running、把功放关掉，于是会出现"running=false 但 dac_path_on /
   * adc_path_on 仍为真"的合法状态。这种情况下再调 hw_stop()，旧判据会直接
   * 早退，那条还开着的模拟通路就**永远漏关**了（下一位持有者一直带着它跑，
   * 直到下一次 hw_start 又把它当新的开一遍）。加上这三个位之后，
   * 收尾的语义才闭合：只要还有任何一条模拟级开着或功放开着，就走完整流程。
   *   反过来，位都是假时早退是安全的：那些行的作用全是"把 DMA / buffer /
   *   ADC 通路收掉"，没有通路开着就没有对应的东西要收；而无条件 post 出来
   *   的多余计数会被 read() 开头的 nxsem_reset() 清掉（见下面的注释）。
   */

  if (!priv->running && !priv->rx_busy && !priv->rx_aborted &&
      priv->rx_apb == NULL && priv->tx_apb == NULL &&
      !priv->dac_path_on && !priv->adc_path_on && !priv->pa_on)
    {
      /* 早退也要放一次"还卡在 read 里的任务"：设备虽然早停了，但真机上出现过
       * "stop 那次唤醒没生效"，那种情况下录音线程会一直卡在那次等待里（界面
       * 跟着遭殃）。这里补一次和完整流程末尾同样的唤醒 + 会话作废，代价只是
       * 一个信号量计数（read() 开头会 reset 掉），换来的是"任何一次 stop 调用
       * 都不可能留着别人卡住"。 */

      priv->rx_aborted = priv->rx_busy;
      priv->session_gen++;
      nxsem_post(&priv->rx_sem);
      return OK;
    }

  sf32lb52_audio_ev(priv, priv->playback ? SF32LB52_AUDIO_EV_PLAY_END :
                                           SF32LB52_AUDIO_EV_SESS_END);

  /* 收尾的两条 DMAStop 都要**先看句柄状态**：厂商的 `HAL_DMA_Abort()`
   * （DMAStop 内部）不看 State，无条件关中断 / 关通道 / 清该通道全部标志
   * （bf0_hal_dma.c:938-963），而对一个已经收好尾的句柄再 abort 一次，写的是
   * 那个**物理通道**的寄存器 —— 它可能已经被别的 DMA 用户重新分配走了
   * （本构建开了动态通道分配，见 sf32lb52_audio_rx_dma_stop_if_armed 的说明），
   * 等于把别人的通道静默关掉。`HAL_DMA_Abort()` 自己会把 State 置成 READY，
   * 所以"READY 就是已经收过尾"这个判据在几处用的是同一条。
   *
   * TX0 这一条单独说清楚（只加守卫、不删不改）：本固件的播放走 codec 自带 DMA
   * （HAL_AUDCODEC_Transmit_DMA，见 hw_start 的说明），AUDPRC TX0 只在队列模式
   * （enqueuebuffer）里才会真的起来，而本板两个 app 走的都是 read()/write()
   * 直通 —— 所以它平时一直是空转。但 sf32lb52_audio_enqueuebuffer 里那条
   * HAL_AUDPRC_Transmit_DMA 还在，队列模式真被用起来时这条 abort 就是必要的
   * 收尾，因此按"不确定就别动"的规矩**保留**；加了守卫之后它平时也不会再写
   * 别人的通道，两边的目的都达到了。 */

  if (priv->aprc.hdma[HAL_AUDPRC_TX_CH0] == NULL ||
      priv->aprc.hdma[HAL_AUDPRC_TX_CH0]->State != HAL_DMA_STATE_READY)
    {
      HAL_AUDPRC_DMAStop(&priv->aprc, HAL_AUDPRC_TX_CH0);
    }

  if (priv->aprc.hdma[HAL_AUDPRC_RX_CH0] == NULL ||
      priv->aprc.hdma[HAL_AUDPRC_RX_CH0]->State != HAL_DMA_STATE_READY)
    {
      HAL_AUDPRC_DMAStop(&priv->aprc, HAL_AUDPRC_RX_CH0);
    }

  __HAL_AUDPRC_DISABLE(&priv->aprc);

