ser = serial.Serial('/dev/ttyACM0', 1000000, timeout=0.2)

def drain(t=1.5):
    time.sleep(t)
    return ser.read(ser.in_waiting or 1).decode(errors='replace')

def send(cmd, wait=2.0):
    ser.write(cmd.encode() + b'\n')
    ser.flush()
    return drain(wait)

send('', 0.5)
