1815	 * Name: sf32lb52_audio_hw_start
1816	 *
1817	 * Description:
1818	 *   启动播放或录音通路（参考 SDK audprc 例程 start_tx/start_rx）：
1819	 *   播放：codec DAC 模拟 → AUDPRC TX 通路 → 功放
1820	 *   录音：codec ADC 模拟 → AUDPRC RX 通路
1821	 *
1822	 ****************************************************************************/
1823	
1824	static int sf32lb52_audio_hw_start(FAR struct sf32lb52_audio_s *priv,
1825	                                   bool playback)
1826	{
1827	  AUDCODEC_HandleTypeDef *codec = &priv->codec;
1828	  AUDPRC_HandleTypeDef   *aprc  = &priv->aprc;
1829	
1830	  sf32lb52_audio_ev(priv, playback ? SF32LB52_AUDIO_EV_PLAY_BEGIN :
1831	                                     SF32LB52_AUDIO_EV_SESS_BEGIN);
1832	
1833	  /* 音频 PLL 时钟配置（播放/录音前必调，参考 SDK bf0_audio_pll_config） */
1834	
1835	
1836	  /* 参考源/带隙基准（含 BG_CFG0 VREF_SEL、REFGEN 使能）：SDK 的 bf0_enable_pll
1837	   * 内部会调用 HAL_TURN_ON_PLL，openvela 的 weak 版本没有 → 必须显式补齐，
1838	   * 否则 DAC 模拟级无参考源，播放静音（录音通路的 ADCPath 自带这一步） */
1839	
1840	  HAL_TURN_ON_PLL();
1841	
1842	  /* SDK 的 52X 参考序列（codec_hp_sin1k_test）在此板上用 VREF_SEL=0xc（AVDD 3.3V，
1843	   * AVDD_V18_ENABLE 未定义走 #else 分支）；openvela 的 HAL_TURN_ON_PLL 写的是 4，
1844	   * 带隙基准不正确 → DAC 模拟级无输出（只有通路开关爆音）。这里按 SDK 值纠正。 */
1845	
1846	  codec->Instance->BG_CFG0 &= ~AUDCODEC_BG_CFG0_VREF_SEL_Msk;
1847	  codec->Instance->BG_CFG0 |= (0xcUL << AUDCODEC_BG_CFG0_VREF_SEL_Pos);
1848	  up_mdelay(2);
1849	
1850	
1851	  /* 音频 PLL 是否真的锁定：UNLOCK=1 表示未锁定 → DAC 无模拟时钟 → 静音 */
1852	
1853	  /* 播放与录音通路一起使能：播放走 codec 自带 DMA（AUDCODEC DAC_CH0，
1854	   * 见 write()），录音走 AUDPRC RX0；两者可独立使用 */
1855	
1856	  /* 注意：播放数据不再经 AUDPRC（改走 codec 自带 DMA，
1857	   * HAL_AUDCODEC_Transmit_DMA），避免 AUDPRC 的 DAC 通路与 codec DMA
1858	   * 争抢 codec 的 DAC 数据源；AUDPRC 现在只负责录音(RX)。 */
1859	
1860	  /* AUDPRC：ADC 输入来自 codec */
1861	
1862	  __HAL_AUDPRC_ADC_SRC_CODEC(aprc);
1863	
1864	  /* 每次会话开始都把 AUDPRC 数字侧的录音配置重写一遍（时钟分频 / 主分频 /
1865	   * ADC 通路 / RX 通道格式），值全部取自 hw_configure 缓存下来的参数。
1866	   *
1867	   * 为什么要在这里多做一遍：hw_stop()/hw_shutdown() 收尾时会做 AUDPRC 软复位
1868	   * （厂商序列，见 sf32lb52_audio_aprc_soft_reset 的注释），复位可能连带清掉
1869	   * CFG.AUDCLK_DIV / STB / ADC_PATH_CFG0 / RX_CH0_CFG —— 那些原来只有 CONFIGURE
1870	   * 那一次写过。而 sf32lb52_audio_start() 在检测到残留 running 时是
1871	   * "stop + start"、中间**没有** CONFIGURE 的（见 sf32lb52_audio_start），
1872	   * 不重写就会用一套空配置录音（DMA 正常起、数据全 0）。
1873	   *
1874	   * CONFIGURE 从没跑过时（samplerate 还是 0）跳过 —— 和 hw_stop()/hw_shutdown()
1875	   * 里那记软复位**共用同一个判据**，两边的开关永远是同向的（见
1876	   * sf32lb52_audio_aprc_has_config 的注释）。
1877	   * 这几行都是普通寄存器写 —— RX_CH0_CFG 那条没有 HAL_AUDPRC_Config_DACPath
1878	   * 里那种"等 SRC_CH_CLR_DONE"的忙等，不会在这里卡住。 */
1879	
1880	  if (sf32lb52_audio_aprc_has_config(priv))
1881	    {
1882	      sf32lb52_audio_aprc_restore_adc(priv);
1883	    }
1884	
1885	  /* RX 通路的会话账在这里立起来 —— 就是厂商 bf0_audio_start 里那一次
1886	   * HAL_AUDPRC_Receive_DMA 所在的位置（它在 __HAL_AUDPRC_ENABLE 之前 arm、
1887	   * 拿 ENABLE 收尾）。
1888	   *
1889	   * 本驱动**不在这里 arm**，只做 arm 的前置条件，原因只有一个：厂商那次
1890	   * Receive_DMA 挂的是驱动自有的接收 buffer（haudprc->buf[RX_CH0]），而本驱动
1891	   * 的 read() 是"直接读进调用者给的 buffer"——hw_start 这一刻还没有任何调用者
1892	   * buffer 可挂，那一次武装只能发生在 read 里（详见文件顶部"录音 RX 通路"那段）。
1893	   * 于是这一段的职责是让 read 的那一次 Receive_DMA **一定落在干净的 READY 上**：
1894	   *   - 上一条会话若把句柄留在非 READY（abort 没走到 / 上一次收尾被跳过），
1895	   *     这里只 abort 一次把它收干净。判据用 hdma->State，与别处同一条：
1896	   *     已经 READY 就绝不再 abort（重复 abort 写的是可能已被别人分配走的
1897	   *     物理通道）；
1898	   *   - 两个 State 都摆成 READY：HAL_DMA_Start_IT 只在 READY 时才真发传输，
1899	   *     而 HAL_AUDPRC_Receive_DMA 把它的返回值丢掉、自己无条件 return HAL_OK，
1900	   *     状态不对就会变成"以为起来了、其实没起"，一路干等 5 秒；
1901	   *   - 会话闸清 0（关着）：上一条会话残影的完成中断从此进不了 read 的等待，
1902	   *     要等本会话第一次 read 武装成功时才会被写上本次会话代号。
1903	   *
1904	   * 不碰 ADC 通路、不软复位、不动 RX_CH0_CFG：软复位是会话边界（hw_stop /
1905	   * hw_shutdown）的事，这里只是让"武装"有个干净的落点。 */
1906	
1907	  {
1908	    sf32lb52_audio_rx_dma_stop_if_armed(priv);
1909	    priv->rx_arm_gen = 0;
1910	  }
1911	
1912	  __HAL_AUDPRC_ENABLE(aprc);
1913	
1914	  /* 首次播放时挂上 codec 自带 DMA 句柄（SDK 52X 的播放路径，小智固件实测有声），
1915	   * 并让 HAL 重新初始化（它会用音频参数配置句柄并动态分配 DMA 通道）。
1916	   *
1917	   * ★ 2026-09-19：这一段的失败分支原来是**静默继续**的 —— 两个 kmm_zalloc 的
1918	   * 结果没人看、HAL_AUDCODEC_Init 的返回值（cret）也没人看。而 HAL_AUDCODEC_Init
1919	   * 只会"跳过" NULL 句柄、照样返回 HAL_OK：于是现场是"录音正常、播放永远没声"
1920	   * 这种最难查的形状（HAL_AUDCODEC_Transmit_DMA 判到 NULL 就 HAL_ERROR，没人报）。
1921	   * 堆被 cJSON / TTS / MQTT 队列吃紧之后（报警那一路正是这种时刻）这个分支真会走到。
1922	   * 现在如实失败并把错误码交回上层：
1923	   *   - 播放（playback=1）：直接返回错误，这一次播报不响，但设备状态一点没动；
1924	   *   - 录音（playback=0）：录音走的是 AUDPRC RX0，不经过 codec 的 DMA，句柄缺了
1925	   *     不影响本次 START，只记一行错误继续（不让"分配失败"顺手把常听也停掉）。
1926	   * 失败时把句柄放回并清成 NULL：下一次 START 会重新分配重试（不清的话这一段的
1927	   * 判据 `hdma[CH0] == NULL` 永远不成立，坏状态就钉死了）。 */
1928	
1929	  if (priv->codec.hdma[HAL_AUDCODEC_DAC_CH0] == NULL)
1930	    {
1931	      int cret;
1932	
1933	      priv->codec.hdma[HAL_AUDCODEC_DAC_CH0] = kmm_zalloc(sizeof(DMA_HandleTypeDef));
1934	      priv->codec.hdma[HAL_AUDCODEC_DAC_CH1] = kmm_zalloc(sizeof(DMA_HandleTypeDef));
