1939	           * 为 NULL 会进 HAL_ASSERT(0)（while(1)）死循环。若该通道已被占用，
1940	           * 分配器会自动改选池里空闲的通道。 */
1941	          priv->codec.hdma[HAL_AUDCODEC_DAC_CH0]->Instance     = DMA1_Channel2;
1942	          priv->codec.hdma[HAL_AUDCODEC_DAC_CH0]->Init.Request = AUDCODEC_DAC0_DMA_REQUEST;
1943	          priv->codec.hdma[HAL_AUDCODEC_DAC_CH0]->Parent       = &priv->codec;
1944	        }
1945	
1946	      if (priv->codec.hdma[HAL_AUDCODEC_DAC_CH1] != NULL)
1947	        {
1948	          priv->codec.hdma[HAL_AUDCODEC_DAC_CH1]->Instance     = DMA1_Channel3;
1949	          priv->codec.hdma[HAL_AUDCODEC_DAC_CH1]->Init.Request = AUDCODEC_DAC1_DMA_REQUEST;
1950	          priv->codec.hdma[HAL_AUDCODEC_DAC_CH1]->Parent       = &priv->codec;
1951	        }
1952	
1953	      if (priv->codec.hdma[HAL_AUDCODEC_DAC_CH0] == NULL ||
1954	          priv->codec.hdma[HAL_AUDCODEC_DAC_CH1] == NULL)
1955	        {
1956	          syslog(LOG_ERR,
1957	                 "AUDIO: codec DMA 句柄分配失败（ch0=%p ch1=%p）：%s\n",
