216	 * Name: audio_close
217	 *
218	 * Description:
219	 *   This function is called when the Audio device is closed.
220	 *
221	 ****************************************************************************/
222	
223	static int audio_close(FAR struct file *filep)
224	{
225	  FAR struct inode *inode = filep->f_inode;
226	  FAR struct audio_upperhalf_s *upper = inode->i_private;
227	  FAR struct audio_openpriv_s *priv = filep->f_priv;
228	  FAR struct audio_openpriv_s *curr;
229	  FAR struct audio_openpriv_s *prev;
230	  irqstate_t flags;
231	  int ret;
232	
233	  /* Get exclusive access to the device structures */
234	
235	  ret = nxmutex_lock(&upper->lock);
236	  if (ret < 0)
237	    {
238	      return ret;
239	    }
240	
241	  flags = spin_lock_irqsave(&upper->spinlock);
242	
243	  /* find and drop priv from list */
244	
245	  for (prev = NULL, curr = upper->head; curr && curr != priv;
246	       prev = curr, curr = curr->flink);
247	
248	  if (prev)
249	    {
250	      prev->flink = priv->flink;
251	    }
252	  else
253	    {
