502	
503	int audio_in_stop(void)
504	{
505	  pid_t owner;
506	  pid_t owner_group;
507	  int fd;
508	  int errcode;
509	
510	  if (nxmutex_lock(&g_audio_in_lock) < 0)
511	    {
