513	    }
514	
515	  fd = g_audio_in_fd;
516	
517	  if (fd < 0)
518	    {
519	      nxmutex_unlock(&g_audio_in_lock);
520	      return OK;                      /* 没在录音，安全空操作 */
521	    }
522	
523	  if (g_audio_in_stop_pending)
524	    {
525	      /* 已经有一个线程正在停这次会话（全局还没清就说明它还没停完）。
526	       * 放行会让两个线程拿到同一个 fd 各 close 一次 —— 第二次 close 关掉的
527	       * 可能是这个槽位刚被别人复用的 fd，所以这里直接空转返回。
528	       *
529	       * 但要先确认那个线程还在：停的动作在锁外做（ioctl 不能持锁），万一它在
530	       * 中途被删/被杀，标志就永远是残留、别人再也停不掉这个会话了。判据沿用
531	       * start() 里那套"持有者线程还在不在"的做法，自愈。 */
532	
533	      FAR struct tcb_s *stopper = nxsched_get_tcb(g_audio_in_stop_owner);
534	      pid_t   stopper_tid       = g_audio_in_stop_owner;
535	      clock_t now;
536	
537	      if (stopper != NULL)
538	        {
539	          nxsched_put_tcb(stopper);
540	          nxmutex_unlock(&g_audio_in_lock);
541	          now = clock_systime_ticks();
542	
543	          /* 空转返回 OK 这件事，调用方**看不出来**（返回值与"真停掉了"完全一样），
544	           * 所以这里留一条限频日志：真有线程卡在收尾里，就会持续留痕，而不是
545	           * 一声不响地报成功。限频是必须的 —— 空转一旦发生就是每次调用都发生，
546	           * 不限频会把串口刷满、反而冲掉有用的上下文。
547	           * **只加日志、不动返回值**：调用方现在把 OK 当"设备已停"，
548	           * 改返回码会牵动它们的语义（见头文件里"第三种 OK"那段）。 */
549	
550	          if ((int32_t)(now - g_audio_in_stop_spin_log_next) >= 0)
551	            {
552	              g_audio_in_stop_spin_log_next =
553	                now + MSEC2TICK(AUDIO_IN_STOP_SPIN_LOG_MS);
554	              syslog(LOG_WARNING,
555	                     "AUDIO_IN: 本次 stop **空转**：线程 %d 仍在收尾这一次会话"
556	                     "（fd=%d），会话没被停、fd 没关，这里照旧返回 OK。"
557	                     "反复出现即说明那个线程卡在 ioctl/close 里回不来了\n",
558	                     (int)stopper_tid, fd);
559	            }
560	
561	          return OK;
562	        }
563	
564	      syslog(LOG_WARNING,
565	             "AUDIO_IN: 上一次停会话的线程 %d 已消失，清掉残留的 stop 标志\n",
566	             (int)g_audio_in_stop_owner);
567	      g_audio_in_stop_pending = false;
568	    }
569	
570	  owner       = g_audio_in_owner;
571	  owner_group = g_audio_in_owner_group;
572	  g_audio_in_stop_pending = true;
573	  g_audio_in_stop_owner   = nxsched_gettid();
574	
575	  nxmutex_unlock(&g_audio_in_lock);
576	
577	  /* 跨组调用要先确认这个 fd 到底通到哪个设备，再决定动不动它。
578	   *
579	   * 为什么不能只看组号就拒绝：task_create() 出来的子任务（hw_test 的读任务就是）
580	   * 会复制父任务的 fd 表，它的同号 fd 指向**同一个 file 对象**，对本板音频设备
581	   * 完全有效 —— 一刀切拒绝会把这种合法用法也挡掉。
582	   * 为什么不能不看就发 STOP：fd 号只在开它的那个组里保证有意义。别组的同号 fd
583	   * 是另一个 file 对象，音频命令号会落到**那个设备自己的 ioctl 处理函数**上 ——
584	   * 真机事故（AUDIOIOC_STOP failed: 25）正是这么来的：命令问到了 robot_ui 组里
585	   * 另一个东西上，音频驱动压根没收到。
586	   * 所以这里先做一次只读探测（GETCAPS(QUERY)，不改任何状态），探测不通过就
