599	             fd, (int)owner_group, (int)owner, (int)getpid(),
600	             (int)nxsched_gettid());
601	
602	      if (nxmutex_lock(&g_audio_in_lock) == 0)
603	        {
604	          g_audio_in_stop_pending = false;
605	          g_audio_in_stop_owner   = (pid_t)-1;
606	          nxmutex_unlock(&g_audio_in_lock);
607	        }
608	
609	      return -EPERM;
610	    }
