  flags = spin_lock_irqsave_nopreempt(&upper->spinlock);
  upper->status->tail++;
  audio_try_enqueue(upper);
  for (priv = upper->head; priv != NULL; priv = priv->flink)
    {
      if (priv->fd)
        {
          eventset = POLLIN | POLLOUT;
          if ((long)(priv->head - upper->status->tail) <= 0)
