static int rndis_handle_control_message(FAR struct rndis_dev_s *priv,
                                        FAR uint8_t *dataout,
                                        uint16_t outlen)
{
  FAR struct rndis_command_header *cmd_hdr;

  /* The data stage of SEND_ENCAPSULATED_COMMAND must carry at least the
   * message header; a NULL/short buffer used to be dereferenced blindly.
