    {
      uerr("RNDIS control message without data stage (%u bytes)\n",
           (unsigned)outlen);
      return -EINVAL;
    }

  cmd_hdr = (FAR struct rndis_command_header *)dataout;

  switch (cmd_hdr->msgtype)
    {
      case RNDIS_INITIALIZE_MSG:
        {
