#!/usr/bin/env python3
"""板子串口持续抓取（带毫秒时间戳，重插自动重开）。
用法: python3 ~/board_serial_capture.py [输出文件，默认 /tmp/board_boot.log]
按 Ctrl-C 或 kill 停止。"""
import os, sys, time, glob, select

LOG = sys.argv[1] if len(sys.argv) > 1 else '/tmp/board_boot.log'

def ts():
    t = time.time()
    return time.strftime('%H:%M:%S', time.localtime(t)) + f'.{int(t*1000)%1000:03d}'

with open(LOG, 'a', buffering=1) as log:
    log.write(f"[{ts()}] === capture loop start (pid {os.getpid()}) ===\n")
    while True:
        paths = sorted(glob.glob('/dev/ttyACM*'))
        if not paths:
            time.sleep(0.2)
            continue
        for p in paths:
            try:
                fd = os.open(p, os.O_RDONLY | os.O_NOCTTY)
            except OSError:
                continue
            log.write(f"[{ts()}] --- open {p} ---\n")
            try:
                while True:
                    r, _, _ = select.select([fd], [], [], 2.0)
                    if not r:
                        continue
                    try:
                        data = os.read(fd, 4096)
                    except OSError:
                        data = b''  # 设备被拔
                    if not data:
                        break  # EOF/断开
                    for ln in data.split(b'\n'):
                        ln = ln.rstrip(b'\r')
                        if ln:
                            log.write(f"[{ts()}] {ln.decode('utf-8', 'replace')}\n")
            finally:
                os.close(fd)
                log.write(f"[{ts()}] --- close {p} ---\n")
        time.sleep(0.2)

