#!/usr/bin/env python3
"""板子串口持续抓取（带毫秒时间戳，重插自动重开）。
用法: python3 ~/board_serial_capture.py [输出文件，默认 /tmp/board_boot.log]
按 Ctrl-C 或 kill 停止。"""
import os, sys, time, glob, select, termios

LOG = sys.argv[1] if len(sys.argv) > 1 else '/tmp/board_boot.log'

def setup_port(fd):
    """板子串口 = 1000000 8N1 raw。重插后节点默认 9600，错波特率会把
    全部数据变成 break 帧被 tty 层丢掉——一行都读不到。"""
    attrs = termios.tcgetattr(fd)
    speed = getattr(termios, 'B1000000', None)
    if speed is None:
        speed = termios.B115200  # 理论上不会发生，glibc 都有 B1000000
    attrs[4] = speed
    attrs[5] = speed
    attrs[0] = 0                                        # iflag raw
    attrs[1] = 0                                        # oflag raw
    attrs[2] = termios.CS8 | termios.CREAD | termios.CLOCAL
    attrs[3] = 0                                        # lflag raw
    termios.tcsetattr(fd, termios.TCSANOW, attrs)
    termios.tcflush(fd, termios.TCIOFLUSH)

