        }

      if (write(dstfd, buf, (size_t)nread) != nread)
        {
          serr("WARN: write %s failed: %d\n", dstpath, errno);
          break;
        }

      total += nread;
    }

  close(dstfd);
  close(srcfd);

  syslog(LOG_INFO, "INFO: agent config installed (%ld bytes)\n", (long)total);
}

