static int rndis_submit_rdreq(FAR struct rndis_dev_s *priv)
{
  int ret = OK;

  if (!priv->rdreq_submitted && !priv->rx_blocked)
    {
      /* Set the flag *before* handing the request to the UDC.  A UDC is
       * allowed to complete a request synchronously from submit(): it may
       * already have a packet parked in the endpoint FIFO, in which case
       * EP_SUBMIT() reads it, runs the completion callback, and that
       * callback calls rndis_submit_rdreq() again before EP_SUBMIT()
       * returns.  Setting rdreq_submitted afterwards overwrote the "not
       * submitted" state which the nested completion had just established,
       * so the driver believed a request was outstanding while the endpoint
       * queue was in fact empty.  Nothing ever re-armed the bulk OUT pipe
       * again: no further read completion, no further RX, permanently.
       */

      priv->rdreq->len      = priv->epbulkout->maxpacket;
      priv->rdreq_submitted = true;

      ret = EP_SUBMIT(priv->epbulkout, priv->rdreq);
      if (ret != OK)
        {
          priv->rdreq_submitted = false;

          usbtrace(TRACE_CLSERROR(USBSER_TRACEERR_RDSUBMIT),
                   (uint16_t)-priv->rdreq->result);
        }
    }

  return ret;
}

input.new_string:
static int rndis_submit_rdreq(FAR struct rndis_dev_s *priv)
{
  irqstate_t flags;
  int ret = OK;

  /* 2026-10-12 真机定案（第二次）：本函数有两个并发调用点 ——
   * rxdispatch 尾部（ETHWORK worker，CPU-B）和 freewrreq（bulk IN 写完成
   * 回调，IRQ 上下文，CPU-A）。两边原来都是裸读 rdreq_submitted 做
   * 检查-然后-动作，SMP 上会双双通过检查、把同一个 rdreq EP_SUBMIT 两次
   * —— 厂商 UDC 的 bulk OUT 队列就此损坏：驱动以为请求还在途、endpoint
   * 队列其实已空，RX 永久死亡（板子静默、主机 transmit queue watchdog）。
   * 对话重流量（ASR 上传 + TTS 下载同时打满双向）时必现。
   *
   * 修法：标志检查+占位在 rdlock 里做（关中断自旋锁），EP_SUBMIT 放在
   * 锁外 —— UDC 允许同步完成，嵌套的完成回调会再进 cancel/block 路径取
   * 同一把锁，锁内调 EP_SUBMIT 会死锁。占位后只有本调用者会提交，
   * 另一调用点看到 rdreq_submitted=true 直接返回。
   */

  flags = spin_lock_irqsave(&priv->rdlock);
  if (!priv->rdreq_submitted && !priv->rx_blocked)
    {
      /* Set the flag *before* handing the request to the UDC.  A UDC is
       * allowed to complete a request synchronously from submit(): it may
       * already have a packet parked in the endpoint FIFO, in which case
       * EP_SUBMIT() reads it, runs the completion callback, and that
       * callback calls rndis_submit_rdreq() again before EP_SUBMIT()
       * returns.  Setting rdreq_submitted afterwards overwrote the "not
       * submitted" state which the nested completion had just established,
       * so the driver believed a request was outstanding while the endpoint
       * queue was in fact empty.  Nothing ever re-armed the bulk OUT pipe
       * again: no further read completion, no further RX, permanently.
       */

      priv->rdreq->len      = priv->epbulkout->maxpacket;
      priv->rdreq_submitted = true;

      spin_unlock_irqrestore(&priv->rdlock, flags);

      ret = EP_SUBMIT(priv->epbulkout, priv->rdreq);
      if (ret != OK)
        {
          /* EP_SUBMIT 失败时嵌套完成回调可能已经跑过并清过标志，
           * 再清一次无害；反之若没跑过，这里必须清，否则 RX 断臂。 */

          flags = spin_lock_irqsave(&priv->rdlock);
          priv->rdreq_submitted = false;
          spin_unlock_irqrestore(&priv->rdlock, flags);

          usbtrace(TRACE_CLSERROR(USBSER_TRACEERR_RDSUBMIT),
                   (uint16_t)-priv->rdreq->result);
        }
    }
  else
    {
      spin_unlock_irqrestore(&priv->rdlock, flags);
    }

  return ret;
}

