priv->connected            = false;

if (config == priv->config)
  {
    /* Already configured -- Do nothing except re-arm the bulk OUT read.
     *
     * A bus reset cancels every queued request (the UDC's reset branch
     * calls cancelrequests() on all endpoints) but leaves priv->config
     * set, so on re-enumeration the host's SET_CONFIGURATION lands here.
     * Returning without re-submitting leaves the bulk OUT pipe with no
     * read request for the rest of the session: the controller then NAKs
     * every packet and not a single frame is received again.  That is
     * exactly what happened after a port swap.
     */

    usbtrace(TRACE_CLSERROR(USBSER_TRACEERR_ALREADYCONFIGURED), 0);

    if (priv->epbulkout != NULL && priv->rdreq != NULL)
      {
        irqstate_t flags = enter_critical_section();

        priv->rdreq->callback = rndis_rdcomplete;
        priv->rx_blocked      = false;
        priv->rdreq_submitted = false;
        (void)rndis_submit_rdreq(priv);

        leave_critical_section(flags);
      }

    return 0;
  }

/* Discard the previous configuration data */

usbclass_resetconfig(priv);

/* Was this a request to simply discard the current configuration? */

if (config == RNDIS_CONFIGIDNONE)
