/* Control transfer bookkeeping for the EP0 OUT data stage.
 *
 * A USB control transfer with an OUT data stage sends the SETUP packet and
 * the data in two separate packets.  When the SETUP interrupt fires the data
 * has not arrived yet (rxcount == 0), so the request must be parked here and
 * finished by the interrupt that delivers the data.
 */

static struct usb_ctrlreq_s g_ep0pending_ctrl;
static bool                 g_ep0pending;

static uint8_t g_ep0outbuf[SF32LB52_EP0MAXPACKET];
static size_t  g_ep0outlen;
static bool    g_ep0outdataend;

static void sf32lb52_dispatchrequest(struct sf32lb52_usbdev_s *priv,
                                     const struct usb_ctrlreq_s *ctrl)
{
  uint8_t *dataout = NULL;
  size_t outlen = 0;
  int ret;

  usbtrace(TRACE_INTDECODE(SF32LB52_TRACEINTID_DISPATCH), 0);

  if (g_ep0outlen > 0)
    {
      dataout = g_ep0outbuf;
      outlen  = g_ep0outlen;
      g_ep0outlen = 0;
    }

  if (priv && priv->driver)
    {
      ret = CLASS_SETUP(priv->driver, &priv->usbdev, ctrl, dataout, outlen);
      if (ret < 0)
        {
          usbtrace(TRACE_DEVERROR(SF32LB52_TRACEERR_STALLEDISPATCH),
                   ctrl->req);
          priv->stalled = 1;
        }
    }
}

