                 * device, then the configuration descriptor is provided by
                 * logic in the composite device implementation.
                 */

#ifndef CONFIG_RNDIS_COMPOSITE
#  ifdef CONFIG_USBDEV_DUALSPEED
                case USB_DESC_TYPE_OTHERSPEEDCONFIG:
#  endif /* CONFIG_USBDEV_DUALSPEED */
                case USB_DESC_TYPE_CONFIG:
                  {
                    int i;
                    ret = usbclass_mkcfgdesc(ctrlreq->buf, &priv->devinfo,
                                             dev->speed, ctrl->value[1]);
                    for (i = 0; i + 16 <= ret; i += 16)
                      {
                        uinfo("cfg[%02d] %02x %02x %02x %02x %02x %02x %02x %02x"
                              " %02x %02x %02x %02x %02x %02x %02x %02x\n",
                              i, ctrlreq->buf[i], ctrlreq->buf[i + 1],
                              ctrlreq->buf[i + 2], ctrlreq->buf[i + 3],
                              ctrlreq->buf[i + 4], ctrlreq->buf[i + 5],
                              ctrlreq->buf[i + 6], ctrlreq->buf[i + 7],
                              ctrlreq->buf[i + 8], ctrlreq->buf[i + 9],
                              ctrlreq->buf[i + 10], ctrlreq->buf[i + 11],
                              ctrlreq->buf[i + 12], ctrlreq->buf[i + 13],
                              ctrlreq->buf[i + 14], ctrlreq->buf[i + 15]);
                      }
                  }
                  break;
#endif

#ifndef CONFIG_RNDIS_COMPOSITE
                case USB_DESC_TYPE_STRING:
                  {
                    /* index == language code. */

                    ret = usbclass_mkstrdesc(ctrl->value[0],
                                  (FAR struct usb_strdesc_s *)ctrlreq->buf);
