hw->index = 0;
csr0 = hw->csr0_txcsr;
if (csr0 & USB_CSR0_P_SETUPEND)
  {
    hw->csr0_txcsr = USB_CSR0_P_SVDSETUPEND;

    /* A new SETUP superseded whatever control transfer was in flight.
     * If a class/vendor OUT request was parked waiting for its data
     * stage, that data will never arrive -- the bytes now in the FIFO
     * are the new SETUP packet itself.  Flag it so the pending branch
     * below abandons the stale request instead of consuming the SETUP
     * as "data" (which produced 8-byte RNDIS messages, a driver
     * -EINVAL, an ep0 STALL and host-side "RNDIS init failed, -32").
     */

    g_ep0superseded = true;
  }

/* Distinguish 8-byte setup packets from EP0 OUT data stage payload.
 * CDC ACM open may send class-specific OUT data (for example
 * SET_LINE_CODING). Do not parse that payload as a setup packet.
 */

count0 = hw->rxcount & 0x7f;

if (g_ep0pending && g_ep0superseded)
  {
    /* SETUPEND said a new SETUP replaced the parked request.  Abandon
     * the parked one and process the bytes below as the new SETUP
     * packet.  Never hand them to the class driver as the parked
     * request's data stage -- that is what turned a fresh INIT/QUERY
     * SETUP into an 8-byte "message" and killed the host's bind with
     * a -32 STALL.
     */

    g_ep0pending    = false;
    g_ep0outlen     = 0;
    g_ep0outdataend = false;
  }

g_ep0superseded = false;

if (g_ep0pending)
  {
    /* This is the OUT data stage of the class/vendor request whose SETUP
     * packet we already parsed.  Read the payload and hand it, together
     * with the saved request, to the class driver.
     */

    uint16_t got = 0;
    bool     shortpkt = (count0 < SF32LB52_EP0MAXPACKET);

    if (count0 == 0)
      {
        /* No packet is actually waiting (rxcount==0): this call is a
         * duplicate service of the SETUP interrupt -- INTRTX CONTROL
         * and INTRRX EP0 both route to here, and the first call has
         * already cleared RXPKTRDY.  Dispatching the parked request
         * with an empty data stage made the class driver reject it
         * (-EINVAL → ep0 STALL → host "RNDIS init failed, -32" on
         * cold boot).  Keep the request parked; the real data-stage
         * interrupt will deliver it.
         */

        return;
      }

    if (count0 > 0)
      {
        if (count0 > sizeof(g_ep0outbuf))
          {
            count0 = sizeof(g_ep0outbuf);
          }

        got = (uint16_t)sf32lb52_epread(priv, 0, g_ep0outbuf, count0);
      }

    /* The final (short) OUT packet of a control write must be acknowledged
     * with DATAEND as well.  Without it the core never considers the data
     * stage finished: the next SETUP then raises SETUPEND, and because the
     * SETUPEND branch below used to win the else-if chain, that SETUP was
     * cleared and dropped -- which is exactly how the RNDIS
     * GET_ENCAPSULATED_RESPONSE got lost.  Same rule as the vendor HAL,
     * see bf0_hal_pcd.c:663-669.
     */

    hw->index = 0;
    csr0 = USB_CSR0_P_SVDRXPKTRDY;
    if (shortpkt)
      {
        csr0 |= USB_CSR0_P_DATAEND;
        g_ep0outdataend = true;
      }

    hw->csr0_txcsr = csr0;

    g_ep0pending = false;
    g_ep0outlen  = (size_t)got;

    sf32lb52_dispatchrequest(priv, &g_ep0pending_ctrl);
    return;
  }

if (count0 != USB_SIZEOF_CTRLREQ)
  {
    if (count0 > 0)
      {
        if (count0 > sizeof(ep0payload))
          {
            count0 = sizeof(ep0payload);
          }

        (void)sf32lb52_epread(priv, 0, ep0payload, count0);
      }

    hw->index = 0;
    hw->csr0_txcsr = USB_CSR0_P_SVDRXPKTRDY;
    return;
  }

