210	     * 比继续显示一个假的时间好。 */
211	    if (now <= 0) {
212	        lv_label_set_text(lbl_time, "--:--");
213	        return;
214	    }
215	
216	    /* UTC -> 本地时间（跨天由加法自然进位） */
217	    if (UI_TZ_OFFSET_SEC != 0) {
218	        now += UI_TZ_OFFSET_SEC;
219	    }
220	
221	    if (localtime_r(&now, &tm_buf) == NULL) {
222	        lv_label_set_text(lbl_time, "--:--");
223	        return;
224	    }
225	
226	    lv_label_set_text_fmt(lbl_time, "%02d:%02d",
