    if (lbl_alarm_icon == NULL)
    {
        return;
    }

    lv_opa_t opa = lv_obj_get_style_opa(lbl_alarm_icon, 0);
    lv_obj_set_style_opa(lbl_alarm_icon, (opa == LV_OPA_COVER) ? LV_OPA_50 : LV_OPA_COVER, 0);
}

