187	/* ==================== 状态栏时钟 ==================== */
188	
189	/* 时区偏移：本构建没开 CONFIG_LIBC_LOCALTIME，`localtime` 实际就是 `gmtime`，
190	 * 也就是系统时钟（RTC）给的是 **UTC**。这里手动加偏移显示北京时间（UTC+8）。
191	 * 换时区只改这一个值即可（负值表示西半球）。
192	 *
193	 * 注：更"正规"的做法是开 CONFIG_LIBC_LOCALTIME 并设 TZ，但那会换掉
194	 * mktime/localtime 的实现，而 `RTC_SET_RELATIVE`（sf32lb_rtc.c 的 add_timeout）
195	 * 正好依赖现在这套简化日历换算，**不建议现在动**；显示层加偏移最省事也最可控。 */
196	#define UI_TZ_OFFSET_SEC  (8 * 3600)
197	
198	/* 从系统时钟（硬件 RTC）读一次，刷新状态栏上的时间标签（本地时间）。 */
199	static void ui_clock_refresh(void)
200	{
201	    time_t now = time(NULL);
202	    struct tm tm_buf;
203	
204	    if (lbl_time == NULL) {
205	        return;
206	    }
207	
208	    /* time() <= 0：说明时钟还没被设过（板上没有 RTC 备份电池，
209	     * 冷启动会读到 1900/2000 这类值）—— 用 "--:--" 明确表示"时间不可信"，
210	     * 比继续显示一个假的时间好。 */
211	    if (now <= 0) {
212	        lv_label_set_text(lbl_time, "--:--");
213	        return;
214	    }
215	
216	    /* UTC -> 本地时间（跨天由加法自然进位） */
217	    if (UI_TZ_OFFSET_SEC != 0) {
218	        now += UI_TZ_OFFSET_SEC;
219	    }
220	
221	    if (localtime_r(&now, &tm_buf) == NULL) {
222	        lv_label_set_text(lbl_time, "--:--");
223	        return;
224	    }
225	
226	    lv_label_set_text_fmt(lbl_time, "%02d:%02d",
227	                          tm_buf.tm_hour, tm_buf.tm_min);
228	}
229	
230	static void ui_clock_timer_cb(lv_timer_t *t)
231	{
232	    (void)t;
233	    ui_clock_refresh();
234	}
