239	 * 要么点这里。两者都调 touch_ui_show_menu(MENU_TYPE_MAIN)。 */
240	static void menu_button_event_handler(lv_event_t *e)
241	{
242	    if (lv_event_get_code(e) == LV_EVENT_CLICKED) {
243	        touch_ui_show_menu(MENU_TYPE_MAIN);
244	    }
245	}
