247	static void create_status_bar(lv_obj_t *parent)
248	{
249	    /* 状态栏容器。**现在只放两样：时钟 + 「菜单」按钮。**
250	     *
251	     * 2026-09-14 用户要求删掉原来那三样：「[在线]」状态、「WiFi 100%」、「NET --」——
252	     * 对老人没有任何用处（电量/信号本来就是写死的假值，网络状态只会让人困惑），
253	     * 挤在 40px 高的栏里还占地方。删掉之后：
254	     *   - 时间保留（它是真的，联网自动对时之后是准的）；
255	     *   - 「菜单」按钮**做大**（130×40，占满整栏高度）—— 它是手势失灵时进主菜单
256	     *     唯一的保底入口，老人手指粗，越大越好按。
257	     *
258	     * 注意：`robot_ui_set_status()` / `robot_ui_set_net_status()` 两个 setter
259	     * 都**保留**了（内部都有 NULL 检查），main.c 里那十几处调用点一行都不用改：
260	     *   - set_net_status()：对应标签仍然不创建，恒为 NULL，没有任何显示效果；
261	     *   - set_status()：2026-09-16 起**有显示效果了** —— 它写的不再是状态栏，
262	     *     而是主界面「AI 回复区」里那一行语音状态小字（见 create_ai_reply_area()
263	     *     和 robot_ui_set_status()）。状态栏这一块仍然只有时钟 + 菜单按钮。 */
264	    lv_obj_t *bar = lv_obj_create(parent);
265	    /* 高度 40 → **64**：菜单按钮要做到 52 高才够好点（40 的栏里塞不下），
266	     * 顺便让整块状态栏不那么挤。 */
267	    lv_obj_set_size(bar, LV_PCT(100), 64);
268	    lv_obj_align(bar, LV_ALIGN_TOP_MID, 0, 0);
269	    lv_obj_set_style_bg_color(bar, lv_color_hex(0x2D2D44), 0);
270	    lv_obj_set_style_border_width(bar, 0, 0);
271	    lv_obj_set_style_radius(bar, 0, 0);
272	    lv_obj_set_style_pad_all(bar, 0, 0);
273	    lv_obj_remove_flag(bar, LV_OBJ_FLAG_SCROLLABLE);
274	    /* ⚠️ 这块屏是 **390×450 的圆角屏**：四个角是物理圆角，贴边的控件既会被
275	     * 视觉裁掉、也不好点按（用户反馈"菜单栏不好点"就是这个原因）。
276	     * 所以这里**不用 flex 排布**，改成两个子对象各自对齐：
277	     *   时间  -> 居中（用户要求）
278	     *   按钮  -> 右对齐 + 内缩 28px（躲开右上圆角）
279	     * 圆角半径大约 20~30px，取 28 作为安全内缩。 */
280	
281	    /* 时间标签（居中）：从系统时钟（硬件 RTC）读真实时间，并定时刷新。
282	     *
283	     * 原来这里是写死的 lv_label_set_text(lbl_time, "12:00")，所以主页面顶上
284	     * **永远显示 12:00**，跟板子时间毫无关系。
285	     *
286	     * 数据源用 time(NULL)：NuttX 启动时用 RTC 初始化系统时钟，
287	     * 而 RTC_SET_TIME（含 NSH 的 `date -s`）会同步系统时钟，所以它就是板子的时间。
288	     * 板上没有 RTC 备份电池，掉电后时间会丢，开机后靠联网自动对时校正
289	     * （见 time_sync.c）；也可以手动：date -s "Sep 13 12:00:00 2026"
290	     *
291	     * 注意：本构建没开 CONFIG_LIBC_LOCALTIME，`localtime` 实际就是 `gmtime`，
292	     * 所以**显示的是 UTC**，比北京时间少 8 小时。要显示本地时间得自己加偏移
293	     * （这里刻意不加，保持"屏幕上显示的就是 RTC 里的值"，免得排查时对不上）。 */
294	    lbl_time = lv_label_create(bar);
295	    lv_obj_set_style_text_color(lbl_time, lv_color_hex(0xFFFFFF), 0);
296	    lv_obj_set_style_text_font(lbl_time, &lv_font_ui_24, 0);
297	    lv_obj_align(lbl_time, LV_ALIGN_CENTER, 0, 0);           /* 时间居中 */
298	    ui_clock_refresh();                                      /* 先立刻显示一次 */
299	    clock_timer = lv_timer_create(ui_clock_timer_cb, 10000, NULL);  /* 每 10 秒刷一次 */
300	
301	    /* 「菜单」按钮：主菜单的保底入口（手势不灵时也能进）。
302	     * 120×52 = 比原来的 LV_SIZE_CONTENT×36 大得多（宽度几乎翻倍、高度 +44%），
303	     * 而且**从右上圆角里挪出来**（右移 -28px）—— 之前贴在屏幕角上，
304	     * 圆角把可点区域切掉一块，所以"不好点"。 */
305	    lv_obj_t *btn_menu = lv_btn_create(bar);
306	    lv_obj_set_size(btn_menu, 120, 52);
307	    lv_obj_align(btn_menu, LV_ALIGN_RIGHT_MID, -28, 0);
308	    lv_obj_add_style(btn_menu, &style_btn, 0);
309	    lv_obj_add_event_cb(btn_menu, menu_button_event_handler,
310	                        LV_EVENT_CLICKED, NULL);
311	    lv_obj_t *lbl_menu = lv_label_create(btn_menu);
312	    lv_label_set_text(lbl_menu, "菜单");
313	    lv_obj_set_style_text_font(lbl_menu, &lv_font_ui_24, 0);
314	    lv_obj_center(lbl_menu);
315	}
316	
317	/* ==================== 更新网络状态 ==================== */
318	void robot_ui_set_net_status(const char *text)
319	{
320	    if (lbl_net == NULL || text == NULL) {
321	        return;
322	    }
323	
324	    if (strcmp(lv_label_get_text(lbl_net), text) == 0) {
325	        return;     /* 没变就不动，省一次重绘 */
326	    }
327	
328	    lv_label_set_text(lbl_net, text);
329	    lv_obj_set_style_text_color(lbl_net,
330	                                strncmp(text, "NET OK", 6) == 0

