495	/* ==================== 按钮事件处理 ==================== */
496	static void btn_event_handler(lv_event_t *e)
497	{
498	    lv_event_code_t code = lv_event_get_code(e);
499	    ui_view_t view = (ui_view_t)lv_event_get_user_data(e);
500	
501	    if (code == LV_EVENT_CLICKED) {
502	        switch (view) {
503	            case UI_VIEW_REMIND:
504	                /* 主屏左下角这个按钮以前只弹一句写死的英文示例（"Time to take
505	                 * medicine!"），和真正的提醒列表毫无关系。现在直接走**主菜单
506	                 * 「查看提醒」同一个入口** —— 多一个冗余入口，老人不用先点开主菜单。 */
507	                touch_ui_play_sound("click");
508	                touch_ui_show_menu(MENU_TYPE_REMIND);
509	                break;
510	            case UI_VIEW_SETTING:
511	                touch_ui_show_menu(MENU_TYPE_SETTING);
512	                break;
513	            case UI_VIEW_ALARM:
514	                robot_ui_show_alarm("Abnormal detected!\nPlease confirm if help is needed.");
515	                break;
516	            case UI_VIEW_MAIN:
517	                /* 报警界面 Back 按钮:关闭报警，返回主界面 */
518	                robot_ui_close_alarm();
519	                break;
520	            default:
521	                break;
522	        }
523	    }
524	}
