648	/* ==================== 设置状态 ==================== */
649	/* 写的是主界面「AI 回复区」里那一行语音状态小字（create_ai_reply_area() 建的
650	 * lbl_status）。**状态栏上没有它** —— 状态栏那三样 2026-09-14 已被用户删掉。
651	 *
652	 * 四档和语音链路的四档一一对应（hello_app 的 voice_state_probe()）：
653	 *   空闲 IDLE       「空闲」  灰   不抢眼，它只是"没事，我在"
654	 *   在听 LISTENING  「在听…」 蓝
655	 *   在想 THINKING   「在想…」 橙   识别 / 等大模型这一段
656	 *   在说 SPEAKING   「在说…」 绿
657	 * 文案比语音镜像面板（touch_ui.c 的 voice_state_text：「检测到声音」「正在想…」
658	 * 「正在说话…」）**更短**：面板里那行是大字、有整行的地方，主界面这一行是夹在
659	 * 对话框里的小字，短一点才不会撑宽。颜色两边是同一套（见文件上面那几个
660	 * UI_STATUS_COLOR_*），老人换个屏幕不用重新学。
661	 *
662	 * 提醒中 / 报警两档沿用原来的措辞（它们是别的流程在借这一行，不是语音状态），
663	 * 只把原来的方括号去掉 —— 这一行现在是纯文字状态行，不是状态栏那种标签。
664	 *
665	 * ⚠️ 只能在 LVGL 线程里调（直接碰控件）。非 LVGL 线程一律走 main.c 的 ui_post()
666	 *    （内部 lv_async_call），见那里"跨线程改界面"那一段。
667	 * ⚠️ `default` 分支一个字都不改是**纪律**：认不出来的档位宁可少刷一次，也不要
668	 *    把这一行停在一个错的字上（touch_ui_set_voice_state 和 main.c 的 voice_state
669	 *    分支是同一条规矩）。 */
670	void robot_ui_set_status(robot_status_t status)
671	{
672	    current_status = status;
673	
674	    if (lbl_status) {
675	        switch (status) {
676	            case ROBOT_STATUS_IDLE:
677	                lv_label_set_text(lbl_status, "空闲");
678	                lv_obj_set_style_text_color(lbl_status, UI_STATUS_COLOR_IDLE, 0);
679	                break;
680	            case ROBOT_STATUS_LISTENING:
681	                lv_label_set_text(lbl_status, "在听…");
682	                lv_obj_set_style_text_color(lbl_status, UI_STATUS_COLOR_LISTENING, 0);
683	                break;
684	            case ROBOT_STATUS_THINKING:
685	                lv_label_set_text(lbl_status, "在想…");
686	                lv_obj_set_style_text_color(lbl_status, UI_STATUS_COLOR_THINKING, 0);
687	                break;
688	            case ROBOT_STATUS_SPEAKING:
689	                lv_label_set_text(lbl_status, "在说…");
690	                lv_obj_set_style_text_color(lbl_status, UI_STATUS_COLOR_SPEAKING, 0);
691	                break;
692	            case ROBOT_STATUS_REMINDING:
693	                lv_label_set_text(lbl_status, "提醒中");
694	                lv_obj_set_style_text_color(lbl_status, lv_color_hex(0x9C27B0), 0);
695	                break;
696	            case ROBOT_STATUS_ALARM:
697	                lv_label_set_text(lbl_status, "报警");
698	                lv_obj_set_style_text_color(lbl_status, lv_color_hex(0xF44336), 0);
699	                break;
700	            default:
701	                break;
702	        }
703	    }
704	}
