752	void robot_ui_show_error(const char *title, const char *content)
753	{
754	    lv_obj_t *scr = lv_scr_act();
755	
756	    if (scr == NULL) {
757	        return;
758	    }
759	
760	    /* 同一时刻只留一页：又报错了就换内容，不叠罗汉 */
761	
762	    if (err_panel != NULL) {
763	        lv_obj_del(err_panel);
764	        err_panel = NULL;
765	    }
766	
767	    err_panel = lv_obj_create(scr);
768	    lv_obj_set_size(err_panel, LV_PCT(92), LV_PCT(78));
769	    lv_obj_center(err_panel);
770	    lv_obj_set_style_bg_color(err_panel, lv_color_hex(0x3A1F1F), 0);
771	    lv_obj_set_style_bg_opa(err_panel, LV_OPA_COVER, 0);
772	    lv_obj_set_style_border_width(err_panel, 3, 0);
773	    lv_obj_set_style_border_color(err_panel, lv_color_hex(0xE53935), 0);
774	    lv_obj_set_style_radius(err_panel, 20, 0);
775	    lv_obj_set_flex_flow(err_panel, LV_FLEX_FLOW_COLUMN);
776	    lv_obj_set_flex_align(err_panel, LV_FLEX_ALIGN_SPACE_EVENLY,
777	                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
778	    lv_obj_remove_flag(err_panel, LV_OBJ_FLAG_SCROLLABLE);
779	
