/* ==================== 全屏子页面页眉 ==================== */
/* 64px 全宽：左返回（back_cb==NULL 不建 = 本页必须作答）+ 中标题 + 右实时时钟。
 * 全屏化后的二级页面统一用它 —— 页面自己带时间，顶栏时钟被盖住也不缺时间。 */
lv_obj_t *ui_page_header_create(lv_obj_t *parent, const char *title,
                                lv_event_cb_t back_cb, void *user_data)
{
    lv_obj_t *header = lv_obj_create(parent);
    lv_obj_set_size(header, LV_PCT(100), 64);
    lv_obj_set_style_bg_opa(header, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(header, 0, 0);
    lv_obj_set_style_pad_left(header, 20, 0);   /* 左右 20：躲开 20~30px 屏幕圆角 */
    lv_obj_set_style_pad_right(header, 20, 0);
    lv_obj_remove_flag(header, LV_OBJ_FLAG_SCROLLABLE);
    /* 不用 flex：三块各自对齐，返回按钮贴左、标题居中、时间贴右 */
    lv_obj_set_style_pad_all(header, 0, 0);

    if (back_cb != NULL) {
        lv_obj_t *btn = lv_btn_create(header);
        lv_obj_set_size(btn, 52, 52);
        lv_obj_align(btn, LV_ALIGN_LEFT_MID, 0, 0);
        lv_obj_set_style_bg_color(btn, THEME_GREEN_TINT, 0);
        lv_obj_set_style_radius(btn, 26, 0);
        lv_obj_set_style_shadow_width(btn, 0, 0);
        lv_obj_add_event_cb(btn, back_cb, LV_EVENT_CLICKED, user_data);
        lv_obj_t *lbl = lv_label_create(btn);
        lv_label_set_text(lbl, "<");
        lv_obj_set_style_text_color(lbl, THEME_GREEN_DARK, 0);
        lv_obj_set_style_text_font(lbl, &lv_font_ui_24, 0);
        lv_obj_center(lbl);
    }

    lv_obj_t *lbl_title = lv_label_create(header);
    lv_label_set_text(lbl_title, (title != NULL) ? title : "");
    lv_obj_set_style_text_color(lbl_title, THEME_TEXT_PRIMARY, 0);
    lv_obj_set_style_text_font(lbl_title, &lv_font_ui_24, 0);
    lv_obj_align(lbl_title, LV_ALIGN_CENTER, 0, 0);

    lv_obj_t *lbl_time = ui_clock_label_create(header, THEME_TEXT_PRIMARY);
    lv_obj_align(lbl_time, LV_ALIGN_RIGHT_MID, 0, 0);

    return header;
}

