1	/**
2	 * touch_ui.c - 老人友好触摸交互界面实现
3	 * 针对老人使用习惯优化
4	 */
5	
6	#include "touch_ui.h"
7	#include <stdio.h>
8	#include <string.h>
9	#include <stdlib.h>
10	
11	/* 板级亮度封装（头文件在 board/contest_board/src，路径由 CMakeLists.txt 的
12	 * INCLUDE_DIRECTORIES ${NUTTX_BOARD_ABS_DIR}/src 提供）。亮度滑块只调它，
13	 * 不自己 open("/dev/lcd0") 拼 ioctl。 */
14	#include "sf32lb52_backlight.h"
15	
16	/* 提醒的存与调度（app/robot_ui/reminder_sched.c）：
17	 * 提醒列表的数据放在那里，界面只在"加 / 删 / 查"时调它的接口，
18	 * 不再自己存一份（以前那份 static reminder_t reminders[] 只会显示、到点不响）。 */
19	#include "reminder_sched.h"
20	
21	/* 摔倒事件链的公共定义（app/robot_ui/fall_alarm.h）：
22	 * 这里只用它的两个常量 —— 问的那句话（屏幕上的字和 TTS 念的话必须是同一句，
23	 * 所以字符串只留一份在那边）和等回答的超时（面板上要如实告诉用户"多久之内回答"）。 */
24	#include "fall_alarm.h"
25	
26	/* 跨线程投递口（app/robot_ui/ui_async.c）。本文件里所有"投到 LVGL 线程"的
27	 * 动作都走它，不直接调 lv_async_call() —— 原因见 ui_async.h 开头：
28	 * lv_async_call() 内部往 LVGL 的全局定时器链表插节点，而那次插入在 LVGL
29	 * 9.1 里没有任何锁，多个工作线程同时插会把链表插坏，撞上 LVGL 线程的遍历
30	 * 就是跳到垃圾地址（整机硬故障）。 */
31	#include "ui_async.h"
32	
33	/* 中文字库（实现在 lv_font_ui_16/20/24.c，见 CMakeLists.txt 的 SRCS）。
34	 * 字符集是常用汉字全集（GB2312 6763 字 + ASCII + CJK 标点 + 全角），
35	 * 按改动前 montserrat 的字号分三档：
36	 *   14/16/18 -> lv_font_ui_16   20/22/24 -> lv_font_ui_20   >=28 -> lv_font_ui_24 */
37	LV_FONT_DECLARE(lv_font_ui_16);
38	LV_FONT_DECLARE(lv_font_ui_20);
39	LV_FONT_DECLARE(lv_font_ui_24);
40	
41	/* ==================== 全局变量 ==================== */
42	static lv_obj_t *current_screen = NULL;
43	static lv_obj_t *menu_panel = NULL;
44	static lv_obj_t *setting_panel = NULL;
45	/* "新建提醒"面板（提醒列表上按「+ 新增提醒」弹出来的那一层）。
46	 * 它和 menu_panel / setting_panel 一样是活动屏的孩子，删的时候要一起删。 */
47	static lv_obj_t *new_reminder_panel = NULL;
48	
49	/* 右滑手势状态 */
50	static int32_t swipe_start_x = 0;
51	static bool swipe_tracking = false;
52	/* 同一次滑动可能被屏幕和输入设备各投递一次，用它去重 */
53	static bool swipe_handled = false;
54	
55	/* 当前菜单层级：决定"返回 / 右滑"该回哪一级。
56	 * 主菜单那一层再返回就关掉浮层（回到主界面），子菜单则回主菜单。
57	 * 注：touch_ui_hide_menu() 以前没有任何调用点，菜单浮层因此没有出口，
58	 *     现场表现就是"进了菜单回不去"。 */
59	static menu_type_t current_menu_type = MENU_TYPE_MAIN;
60	
61	/* 当前状态 */
62	static robot_mode_t current_mode = MODE_NORMAL;
63	static settings_t user_settings = {
64	    .volume = 70,
65	    .brightness = 80,
66	    .auto_remind = true,
67	    .remind_interval = 60
68	};
69	
70	/* 提醒数据都在 reminder_sched.c（reminder_item_t / reminder_sched_*），
71	 * 这里只留"新建提醒"面板正在编辑的那几个值。
72	 *
73	 * 面板布局（老人机，屏幕 390x450）：
74	 *   标题 [新建提醒]                                   [×]
75	 *   [吃药] [喝水]
