113	/* 语音聊天弹窗（见文件后半 "语音聊天弹窗" 一节） */
114	static lv_obj_t *voice_panel = NULL;
115	static lv_obj_t *voice_timer_lbl = NULL;
116	static lv_obj_t *voice_status_lbl = NULL;
117	static lv_obj_t *voice_chat_box = NULL;
