124	/* 镜像面板的"双方对话"历史（PTT 弹窗不走这里，原因见 voice_text_async 的注释）。
125	 *
126	 * 为什么是固定槽位而不是一条长字符串：用户的要求是"两边的对话都要看得见、
127	 * 还能往上翻一眼"，一条长字符串没法只丢掉最老的那一轮，聊十句就把面板内容
128	 * 撑到几千像素高。这里固定 VOICE_HISTORY_ROUNDS 轮，写满一轮就把最老的整个
129	 * 删掉重建，所以行数和内存都有上限，面板不会被撑破。
130	 * 每轮两个 label（voice_hist_user / voice_hist_ai）：字号和颜色不同，
131	 * 老人不用细读也能扫一眼分出哪句是自己说的。 */
132	#define VOICE_HISTORY_ROUNDS 3
133	static lv_obj_t *voice_hist_hint = NULL;                    /* 还没说话时的占位行 */
134	static lv_obj_t *voice_hist_user[VOICE_HISTORY_ROUNDS];     /* 每轮的"你说：…" */
135	static lv_obj_t *voice_hist_ai[VOICE_HISTORY_ROUNDS];       /* 每轮的"智爱：…" */
136	static int voice_hist_next = 0;         /* 环形缓冲：下一个要覆盖的槽位 */
137	static int voice_hist_pending = -1;     /* 写了"你说"、还等着写"智爱"的槽位，-1=没有 */
138	
139	/* 提交按钮的三态：可提交 -> 处理中(禁用) -> 可再来一轮 */
140	typedef enum {
141	    VOICE_BTN_SUBMIT = 0,
142	    VOICE_BTN_BUSY,
143	    VOICE_BTN_RETRY
144	} voice_btn_state_t;
145	static voice_btn_state_t voice_btn_state = VOICE_BTN_SUBMIT;
146	
147	/* 投到弹窗里的一段文字是哪一类（决定它写状态行还是进对话历史）。
148	 * 放在这里而不是紧接着 voice_post_text()：它要出现在文件上半的
149	 * "语音聊天弹窗内部函数"前置声明之前，否则那行声明里认不出这个类型。 */
150	typedef enum {
151	    VOICE_TEXT_STATUS = 0,   /* 状态行：写一句话进去，不参与对话历史 */
152	    VOICE_TEXT_USER,         /* 用户发言（ASR 原文）：开一轮新的"你说：…" */
153	    VOICE_TEXT_REPLY         /* 智爱回复：收尾当前这一轮，写"智爱：…" */
154	} voice_text_kind_t;
