294	    lv_style_init(&style_back_btn);
295	    lv_style_set_bg_color(&style_back_btn, lv_color_hex(0x607D8B));
296	    lv_style_set_bg_opa(&style_back_btn, LV_OPA_COVER);
297	    lv_style_set_radius(&style_back_btn, 25);
298	    lv_style_set_text_color(&style_back_btn, lv_color_hex(0xFFFFFF));
299	    lv_style_set_text_font(&style_back_btn, &lv_font_ui_16);
300	
301	    /* 设置滑块样式 */
302	    lv_style_init(&style_slider);
303	    lv_style_set_bg_color(&style_slider, lv_color_hex(0x37474F));
304	    lv_style_set_radius(&style_slider, 10);
305	
306	    /* 开关样式 */
307	    lv_style_init(&style_switch);
308	    lv_style_set_bg_color(&style_switch, lv_color_hex(0x4CAF50));
309	}
310	
311	/* ==================== 初始化触摸交互 UI ==================== */
312	void touch_ui_init(void)
313	{
314	    /* 初始化样式 */
315	    init_elder_styles();
316	
317	    /* 初始化提醒列表（数据在 reminder_sched.c：清空 + 复位调度状态） */
318	    reminder_sched_init();
319	
320	    /* 新建提醒面板的编辑状态复位 */
321	    new_reminder_hour = 8;
322	    new_reminder_min = 0;
323	    new_reminder_preset = 0;
324	    for (int i = 0; i < NEW_REMINDER_PRESET_COUNT; i++) {
325	        new_reminder_preset_btns[i] = NULL;
326	    }
327	    new_reminder_step_lbls[0] = NULL;
328	    new_reminder_step_lbls[1] = NULL;
329	
330	    /* 面板句柄复位: NuttX builtin 应用重新运行时 .bss 不清零,
331	     * 若残留上一次运行的面板指针, 之后 lv_obj_del() 会去删除已
332	     * 失效的 LVGL 对象而导致 hardfault */
333	    menu_panel = NULL;
334	    setting_panel = NULL;
335	    new_reminder_panel = NULL;
336	
337	    /* 语音聊天弹窗同理：定时器与控件都只属于上一次那个 LVGL 实例，
338	     * 不复位就会删到野指针（这里只把句柄清空，不去 del 残留的） */
339	    voice_panel = NULL;
340	    voice_timer_lbl = NULL;
341	    voice_status_lbl = NULL;
342	    voice_chat_box = NULL;
343	    voice_reply_lbl = NULL;
344	    voice_hist_hint = NULL;
345	    for (int i = 0; i < VOICE_HISTORY_ROUNDS; i++) {
346	        voice_hist_user[i] = NULL;
347	        voice_hist_ai[i] = NULL;
348	    }
349	    voice_hist_next = 0;
350	    voice_hist_pending = -1;
351	    voice_submit_btn = NULL;
352	    voice_submit_lbl = NULL;
353	    voice_tick_timer = NULL;
354	    voice_btn_state = VOICE_BTN_SUBMIT;
355	    voice_generation = 0;
356	    voice_mirror_only = false;
357	
358	    /* 获取当前活动屏幕 */
359	    current_screen = lv_scr_act();
360	    lv_obj_add_style(current_screen, &style_elder, 0);
361	
362	    /* 右滑手势：按下/抬起挂在**输入设备**上。
363	     *
364	     * 以前只挂在屏幕上，而主屏的子对象（表情区、各按钮、AI 回复框）在 LVGL 里
365	     * 默认会把触摸事件吃掉（不冒泡给父对象），所以手指落在那些区域上时，
366	     * 屏幕根本收不到 PRESSED/RELEASED —— 现象就是"怎么划都划不出菜单"。
367	     * indev 的事件只看按下/抬起，与命中的对象无关，因此一定能收到。
368	     * 屏幕上的注册保留着（同一次滑动可能两边都来，swipe_handled 去重）。
369	     *
370	     * ⚠ 必须挂到**每一个 pointer 设备**上，不能只挂 lv_indev_get_next(NULL)：
371	     *   - 本机可能有两只手：真触摸（/dev/input0，现在坏了没有）和镜像的
372	     *     鼠标虚拟设备（lcd_mirror_glue.c 建的）。lv_indev_create() 是
373	     *     **_lv_ll_ins_head**（插在表头），所以"第一个"到底是哪一只、取决于
374	     *     谁先建 —— 只挂一只的话，另一只"点得动按钮、却划不出菜单"，
375	     *     现场极难判断（表现成"手势偶尔灵偶尔不灵"）。
376	     *   - 遍历全部 pointer 设备就对两只都生效，而且以后加设备也不用再改这里。 */
377	    {
378	        lv_indev_t *indev;
379	        int         attached = 0;
380	
381	        for (indev = lv_indev_get_next(NULL); indev != NULL;
382	             indev = lv_indev_get_next(indev))
383	          {
384	            if (lv_indev_get_type(indev) != LV_INDEV_TYPE_POINTER)
385	              {
386	                continue;
387	              }
388	
389	            lv_indev_add_event_cb(indev, screen_gesture_event_handler,
390	                                  LV_EVENT_PRESSED, NULL);
391	            lv_indev_add_event_cb(indev, screen_gesture_event_handler,
392	                                  LV_EVENT_RELEASED, NULL);
393	            lv_indev_add_event_cb(indev, screen_gesture_event_handler,
394	                                  LV_EVENT_CANCEL, NULL);
395	            attached++;
396	          }
397	
398	        if (attached == 0)
399	          {
400	            printf("[Gesture] 没找到 pointer 输入设备，右滑只在屏幕上生效\n");
401	          }
402	        else
403	          {
404	            printf("[Gesture] 右滑已挂到 %d 个输入设备\n", attached);
405	          }
406	    }
407	
408	    lv_obj_add_event_cb(current_screen, screen_gesture_event_handler,
409	                        LV_EVENT_PRESSED, NULL);
410	    lv_obj_add_event_cb(current_screen, screen_gesture_event_handler,
411	                        LV_EVENT_RELEASED, NULL);
412	    lv_obj_add_event_cb(current_screen, screen_gesture_event_handler,
413	                        LV_EVENT_CANCEL, NULL);
414	
415	    /* 加载持久化设置 */
416	    settings_load_from_file();
417	
418	    printf("touch_ui init done\n");
419	}
420

