499	/* ==================== 创建菜单面板 ==================== */
500	static void create_menu_panel(menu_type_t type)
501	{
502	    /* 菜单容器 */
503	    menu_panel = lv_obj_create(current_screen);
504	    lv_obj_set_size(menu_panel, LV_PCT(95), LV_PCT(85));
505	    lv_obj_align(menu_panel, LV_ALIGN_CENTER, 0, 0);
506	    lv_obj_add_style(menu_panel, &style_elder, 0);
507	    lv_obj_set_flex_flow(menu_panel, LV_FLEX_FLOW_COLUMN);
508	    lv_obj_set_flex_align(menu_panel, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
509	    lv_obj_set_style_pad_all(menu_panel, 20, 0);
510	    lv_obj_set_style_pad_row(menu_panel, 15, 0);
511	
512	    /* 标题 */
