    lv_obj_t *sw = lv_switch_create(container);
    lv_obj_set_size(sw, 80, 40);
    lv_obj_set_style_bg_color(sw, lv_color_hex(0x4CAF50), LV_PART_MAIN);
    lv_obj_set_style_bg_color(sw, lv_color_hex(0x9E9E9E), LV_PART_INDICATOR);
