1396	/* ==================== 右滑手势处理 ==================== */
1397	
1398	/* 在主屏幕上检测右滑手势，滑动超过 80px 显示主菜单 */
1399	static void screen_gesture_event_handler(lv_event_t *e)
1400	{
1401	    lv_event_code_t code = lv_event_get_code(e);
1402	
1403	    if (code == LV_EVENT_PRESSED) {
1404	        lv_indev_t *indev = lv_indev_get_act();
1405	        if (indev) {
1406	            lv_point_t p;
1407	            lv_indev_get_point(indev, &p);
1408	            swipe_start_x = p.x;
1409	            swipe_tracking = true;
1410	            swipe_handled = false;
1411	        }
1412	    }
1413	    else if (code == LV_EVENT_RELEASED || code == LV_EVENT_CANCEL) {
1414	        if (!swipe_tracking) return;
1415	        swipe_tracking = false;
1416	
1417	        /* 屏幕和 indev 可能各投递一次，只处理第一次 */
1418	        if (swipe_handled) return;
1419	
1420	        lv_indev_t *indev = lv_indev_get_act();
1421	        if (!indev) return;
1422	
1423	        lv_point_t p;
1424	        lv_indev_get_point(indev, &p);
1425	        int32_t dx = p.x - swipe_start_x;
1426	
1427	        /* 向右滑动超过 80px = 返回上一级（与"返回"按钮同语义） */
1428	        if (dx > 80) {
1429	            swipe_handled = true;
1430	
1431	            /* 语音聊天弹窗是模态的：录音/识别在跑的时候右滑切菜单，
1432	             * 会让菜单盖在弹窗上、录音没人收尾。要退请按弹窗里的 ×。 */
1433	            if (voice_panel != NULL) {
1434	                printf("[Gesture] 语音聊天弹窗开着，忽略右滑\n");
1435	                return;
1436	            }
1437	
1438	            printf("[Gesture] Swipe right detected (dx=%d), go back one level\n", (int)dx);
1439	            touch_ui_play_sound("click");
1440	            menu_go_back_one_level();
1441	        }
1442	    }
1443	}
