1454	/* ==================== 弹窗关闭按钮 ==================== */
1455	
1456	/* 给 lv_msgbox 加一个右上角的关闭按钮，标签是真正的 `×`(U+00D7)。
1457	 *
1458	 * 不要用 lv_msgbox_add_close_button()：它画的是 LVGL 内置符号字体（LV_SYMBOL_CLOSE），
1459	 * 而本工程的字库只有 ASCII + 常用符号，那个符号不在里面 —— 屏幕上会显示成一个
1460	 * 白边空心方块（用户反馈过两次）。`×` 在 lv_font_ui_16/20/24 里都有。 */
1461	void touch_ui_msgbox_add_close_x(lv_obj_t *mbox)
1462	{
1463	    lv_obj_t *btn;
1464	
1465	    if (mbox == NULL) {
1466	        return;
1467	    }
1468	
1469	    btn = lv_msgbox_add_header_button(mbox, "×");
1470	    if (btn == NULL) {
1471	        return;
