        case MENU_TYPE_REMIND:
            menu_title = "提醒";
            break;
        case MENU_TYPE_SETTING:
            menu_title = "设置";
            break;
        case MENU_TYPE_ABOUT:
            menu_title = "关于";
            break;
        default:
            break;
