260	 * 面板重新初始化（黑屏救回）
261	 ****************************************************************************/
262	
263	/**
264	 * @brief  面板重初始化之后，把整屏判成脏区重推一次
265	 *
266	 * 跑在 LVGL 线程里（ui_async_call 投过来的），所以这里碰控件是安全的。
267	 *
268	 * 为什么必须显式 invalidate 整屏：面板被复位过，GRAM 里的内容是随机的，
269	 * 面板侧"配置修好了"不等于"画面对了"。LVGL 只重画脏区，而黑屏期间界面
270	 * 往往已经没有脏区了（用户没在操作），光靠"下一帧"可能什么都等不到。
271	 *
272	 * 不在这里调 lv_refr_now()：没必要要求"投递后立刻刷完"，
273	 * LVGL 自己的刷新定时器几十毫秒内就会跑，不值得为省这几十毫秒去冒
274	 * 从定时器回调里再进一次刷新的风险。
275	 */
276	
277	static void panel_reinit_full_redraw(void *arg)
278	{
279	  (void)arg;
280	
281	  lv_obj_invalidate(lv_screen_active());
282	}
283	
284	int robot_ui_bridge_panel_reinit(void)
285	{
286	  int ret;
287	
288	  if (up_interrupt_context())
289	    {
290	      printf("[Bridge] 面板重初始化被挡（在中断上下文里）\n");
291	      return -EINVAL;
292	    }
293	
294	  /* 面板侧：重发初始化序列 + 拉一次 RESET 脚 + 重设像素格式/亮度/DisplayOn。
295	   * 驱动里用 panel_lock 和刷新路径互斥，所以 LVGL 正在推屏也不会打架。 */
296	  ret = sf32lb_lcd_panel_reinit();
297	  if (ret < 0)
298	    {
299	      printf("[Bridge] 面板重初始化失败: %d"
300	             "（-19=面板驱动还没绑上，-38=这个固件里编掉了）\n", ret);
301	      return ret;
302	    }
303	
304	  if (!g_ui_ready)
305	    {
306	      printf("[Bridge] 面板已重初始化；界面还没就绪，"
307	             "全屏重绘等 LVGL 自己刷\n");
308	      return 0;
309	    }
310	
311	  if (ui_async_call(panel_reinit_full_redraw, NULL) != LV_RESULT_OK)
312	    {
313	      printf("[Bridge] 面板已重初始化，但全屏重绘投递失败（内存不够？）"
314	             "—— 先等下一个脏区\n");
315	      return -ENOMEM;
316	    }
317	
318	  printf("[Bridge] 面板已重初始化，已投一次全屏重绘\n");
319	  return 0;
320	}
321	
322	/**
323	 * @brief  每帧看一眼"面板内容是不是已经对不上了"，是就整屏重绘
324	 *
325	 * 为什么需要：驱动侧 putrun/putarea 在**面板还没就绪**的时候是**静默丢弃**
326	 * （vendor/sifli/boards/sf32lb52/drivers/lcd/sf32lb_lcd.c 里那两个
327	 *  `if (s_fb_registering || !s_lcd_hw_ready) return OK;`）。开机时 /dev/fb0
328	 * 一注册好界面就起来了，而面板要等那次完整 Init 才置就绪 —— LVGL 的整屏
329	 * 首帧正好被丢掉，而它自己以为已经画上去了。之后它只重画脏区，于是屏幕
330	 * 一直保持"只有那几个小脏区有内容"：整屏黑、只有状态栏那一小块/刚点开的
331	 * 页面有画面（实测现象）。面板被重初始化（SWRESET 清 GRAM）同理。
332	 *
333	 * 跑在 LVGL 线程里（robot_ui 主循环），所以这里碰控件是安全的。
334	 *
335	 * Returned Value: 这次有没有投一次整屏重绘（只给日志/调试用）。
336	 */
337	
338	bool robot_ui_bridge_lcd_check(void)
339	{
340	  static uint32_t last_ms;
341	  static uint32_t redraw_cnt;
342	  uint32_t now;
343	
344	  if (!g_ui_ready)
345	    {
346	      return false;
347	    }
348	
349	  /* 限速：面板还没就绪时，重绘出去的像素同样会被丢 ⇒ 标志马上又会被置上。
350	   * 不限速就变成"每几毫秒渲染一整屏"的空转，把 LVGL 线程整个占住。
351	   * 250ms 一次：最多白画几帧，面板一就绪下一轮就是完整的一屏。 */
352	  now = lv_tick_get();
353	  if (last_ms != 0 && (uint32_t)(now - last_ms) < 250)
354	    {
355	      return false;                 /* 标志留着，下一轮再看 */
356	    }
357	
358	  last_ms = now;
359	
360	  if (!sf32lb_lcd_take_content_lost())
361	    {
362	      return false;
363	    }
364	
365	  lv_obj_invalidate(lv_screen_active());
366	
367	  redraw_cnt++;
368	  if (redraw_cnt <= 3)
369	    {
370	      printf("[Bridge] 面板内容缺失（丢帧或面板复位）⇒ 整屏重绘第 %u 次\n",
371	             (unsigned)redraw_cnt);
372	    }
373	
374	  return true;
375	}
