import base64, json, ssl, urllib.request

cfg = json.load(open('/home/xiaoyingyu/.mimo/settings.json'))
KEY = cfg['api']['api_key']
URL = '[[REDACTED-TP-KEY]]/chat/completions'
CTX = ssl.create_default_context()

def post(body):
    req = urllib.request.Request(URL, data=json.dumps(body).encode(),
        headers={'Content-Type': 'application/json',
                 'Authorization': 'Bearer ' + KEY})
    try:
        with urllib.request.urlopen(req, timeout=60, context=CTX) as r:
            return r.status, json.loads(r.read())
    except urllib.error.HTTPError as e:
        return e.code, e.read()[:300].decode('utf-8', 'replace')

# 1) TTS：中文问句 -> WAV
st, resp = post({'model': 'mimo-v2.5-tts',
                 'messages': [{'role': 'assistant', 'content': '现在几点了？'}]})
print('TTS status:', st)
if st != 200:
    print('TTS resp:', resp); raise SystemExit(1)
wav_b64 = resp['choices'][0]['message']['audio']['data']
wav = base64.b64decode(wav_b64)
print('WAV bytes:', len(wav))

def asr(variant):
    audio = {'data': wav_b64, 'format': 'wav'}
    content = [{'type': 'input_audio', 'input_audio': audio}]
    body = {'model': 'mimo-v2.5-asr',
            'messages': [{'role': 'user', 'content': content}]}
    if variant == 'in_audio':
        audio['language'] = 'zh'
    elif variant == 'top_level':
        body['language'] = 'zh'
    elif variant == 'user_prompt':
        content.insert(0, {'type': 'text',
                           'text': '请把这段语音转写成简体中文。'})
    st, resp = post(body)
    if st != 200:
        print(f'ASR [{variant}] HTTP {st}: {resp}')
        return
    txt = resp['choices'][0]['message'].get('content') or ''
    print(f'ASR [{variant}] -> {txt!r}')

for v in ('baseline', 'in_audio', 'top_level', 'user_prompt'):
    asr(v)

