 * "语音聊天弹窗内部函数"前置声明之前，否则那行声明里认不出这个类型。 */
typedef enum {
    VOICE_TEXT_STATUS = 0,   /* 状态行：写一句话进去，不参与对话历史 */
    VOICE_TEXT_USER,         /* 用户发言（ASR 原文）：开一轮新的"你说：…" */
    VOICE_TEXT_REPLY         /* 智爱回复：收尾当前这一轮，写"智爱：…" */
} voice_text_kind_t;

