static void voice_start_timer(void)
{
    voice_stop_timer();
    voice_start_tick = lv_tick_get();
    voice_tick_timer = lv_timer_create(voice_tick_timer_cb, 1000, NULL);
}

/* 底部大按钮的三个状态：提交 -> 处理中(禁用) -> 再说一次 */
static void voice_set_btn_state(voice_btn_state_t state)
{
    voice_btn_state = state;

    if (voice_submit_btn == NULL || voice_submit_lbl == NULL) {
        return;
    }

    switch (state) {
        case VOICE_BTN_SUBMIT:
            lv_label_set_text(voice_submit_lbl, "提交");
            lv_obj_clear_state(voice_submit_btn, LV_STATE_DISABLED);
            break;
        case VOICE_BTN_BUSY:
            lv_label_set_text(voice_submit_lbl, "处理中…");
            lv_obj_add_state(voice_submit_btn, LV_STATE_DISABLED);
            break;
        case VOICE_BTN_RETRY:
        default:
            lv_label_set_text(voice_submit_lbl, "再说一次");
            lv_obj_clear_state(voice_submit_btn, LV_STATE_DISABLED);
            break;
    }
}

/* 开一轮新的说话：世代 +1（上一轮在途的结果就此作废），界面归零，计时重开。
 * 录音本身不在这里启动 —— main.c 的 g_voice_chat_cb 负责。
 * 只清空那块整段显示的 label（PTT 弹窗专用），不清镜像面板的历史 —— 这里
 * 压根跑不到镜像面板（它不开麦、不建计时），而 PTT 的一轮结束后历史本来
 * 就只有那一整段。 */
static void voice_begin_round(void)
{
    voice_generation++;

    voice_set_btn_state(VOICE_BTN_SUBMIT);

    if (voice_reply_lbl != NULL) {
        lv_label_set_text(voice_reply_lbl, "");
    }
    if (voice_status_lbl != NULL) {
        lv_label_set_text(voice_status_lbl, "正在录音…\n说完点「提交」");
    }
    if (voice_chat_box != NULL) {
        lv_obj_scroll_to_y(voice_chat_box, 0, LV_ANIM_OFF);
    }
    if (voice_timer_lbl != NULL) {
        lv_label_set_text(voice_timer_lbl, "00:00");
    }

    voice_start_timer();
}

/* × ：结束录音、丢弃这一轮、关窗 */
static void voice_close_event_handler(lv_event_t *e)
{
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) {
        return;
    }

    touch_ui_play_sound("click");

    /* 镜像面板：本来就没录音，不用（也不能）通知 main.c 去停录音 */
    if (voice_mirror_only) {
        printf("[VoiceChat] 关闭镜像面板\n");
        touch_ui_hide_voice_chat();
        return;
    }

    printf("[VoiceChat] 关闭弹窗，丢弃这一轮\n");

    /* 先让 main.c 停录音、丢缓冲，再关窗：关窗会把世代号推进，
     * 在途的 ASR/LLM/TTS 结果回来时会发现对不上，自己丢掉 */
===
    pthread_attr_t attr;
    pthread_t tid;

    (void)user_data;

    /* 用户按了「提交」= 这一轮不再要麦克风了：令牌 +1，让可能还在开麦路上的那条
     * 线程自己作废（否则它会在这一轮之后又把麦开起来，而那时面板上已经
     * 没有「提交」也没有人在等，谁也不会去停它）。 */
    g_voice_open_token++;

    /* 半双工设备：要播 TTS 就得先把麦克风让出来 */
    if (audio_is_recording(&g_audio_ctx)) {
        audio_record_stop(&g_audio_ctx);
    }

    /* 麦克风已经关了：状态栏不该再显示「聆听中」
     * （后面这段是识别/思考/播放，由弹窗里的状态行如实显示进度） */
    voice_ui_idle();

    /* 录音缓冲的所有权转移给任务（不做第二次 320 KB 拷贝；
     * 下一轮录音时再按需 malloc） */
    pthread_mutex_lock(&g_voice_lock);
    pcm = g_voice_pcm;
    pcm_len = g_voice_pcm_len;
    g_voice_pcm = NULL;
    g_voice_pcm_len = 0;
    g_voice_pcm_full = false;
    pthread_mutex_unlock(&g_voice_lock);

    if (pcm == NULL || pcm_len < VOICE_PCM_MIN_BYTES) {
        printf("[VoiceChat] 录音太短 (%zu 字节)，不提交\n", pcm_len);
        free(pcm);
        touch_ui_set_voice_status("没有录到声音\n请再说一次");
        touch_ui_voice_chat_round_done();
        return;
    }

    printf("[VoiceChat] 提交 %zu 字节 PCM (~%u 秒)\n",
           pcm_len, (unsigned int)(pcm_len / (16000 * 2)));

    /* 录音体检：ASR 只回"嗯。"这类极短结果时，先看这段音频本身有没有声音。
     * peak 接近 0 = 麦克风/设备没采到东西（不是模型的问题）——
     * 这条日志是排查"识别成嗯"时唯一的一手依据（对比 hw_test audio 的 peak）。 */
    {
        const int16_t *p = (const int16_t *)pcm;
        size_t n = pcm_len / sizeof(int16_t);
        int32_t peak = 0;
        int64_t sum = 0;
        size_t i;

        for (i = 0; i < n; i++) {
            int32_t v = p[i];

            if (v < 0) {
                v = -v;
            }
            if (v > peak) {
                peak = v;
            }
            sum += v;
        }

        printf("[VoiceChat] PCM 体检: %zu 帧 peak=%d avg=%ld\n",
               n, (int)peak, (long)((n > 0) ? (sum / (int64_t)n) : 0));
    }

    task = voice_task_new(pcm, pcm_len);
    if (task == NULL) {
        free(pcm);
        touch_ui_set_voice_status("内存不足\n请重试");
        touch_ui_voice_chat_round_done();
        return;
    }

    /* 线程必须 detach：用户随时可能关窗，没人会去 join 它；任务自带引用
     * 计数会自释放，所以工作线程跑多久都拖不住界面 */
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
    /* ASR 那层要跑 TLS + HTTPS，栈给足（默认 16 KB 偏紧：ai_companion 里
     * 这条路是跑在 32 KB 的主线程上） */
    pthread_attr_setstacksize(&attr, 32768);

    if (pthread_create(&tid, &attr, voice_worker, task) != 0) {
        pthread_attr_destroy(&attr);
        voice_task_unref(task);
        touch_ui_set_voice_status("识别线程启动失败");
        touch_ui_voice_chat_round_done();
        return;
    }
    pthread_attr_destroy(&attr);

    touch_ui_set_voice_status("正在识别…");
}

/* 「×」：用户放弃这一轮。停录音、丢缓冲；在途的工作线程靠世代号自动作废。 */
static void voice_cancel_handler(void *user_data)
{
    (void)user_data;

    /* 用户按了「×」= 这一轮放弃：令牌 +1，让可能还在开麦路上的那条线程自己
     * 作废（那样它就不会在用户已经走了之后把麦开起来 —— 开了没人会去停）。 */

