 * Name: sf32lb52_epsubmit
 ****************************************************************************/

static int sf32lb52_epsubmit(struct usbdev_ep_s *ep,
                             struct usbdev_req_s *req)
{
  struct sf32lb52_req_s *privreq = (struct sf32lb52_req_s *)req;
  struct sf32lb52_ep_s *privep = (struct sf32lb52_ep_s *)ep;
  struct sf32lb52_usbdev_s *priv;
  irqstate_t flags;
  int ret = OK;

#ifdef CONFIG_DEBUG_FEATURES
  if (!req || !req->callback || !req->buf || !ep)
    {
      usbtrace(TRACE_DEVERROR(SF32LB52_TRACEERR_INVALIDPARMS), 0);
      return -EINVAL;
    }
#endif

  usbtrace(TRACE_EPSUBMIT, privep->epphy);
  priv = privep->dev;

  if (!priv->driver || priv->usbdev.speed == USB_SPEED_UNKNOWN)
    {
      usbtrace(TRACE_DEVERROR(SF32LB52_TRACEERR_NOTCONFIGURED), 0);
      return -ESHUTDOWN;
    }

  req->result = -EINPROGRESS;
  req->xfrd   = 0;
  flags       = enter_critical_section();

  /* Handle stalled endpoint first */

  if (privep->stalled)
    {
      sf32lb52_abortrequest(privep, privreq, -EBUSY);
      ret = -EBUSY;
    }
  else if (req->len == 0 && privep->epphy == 0)
    {
      /* EP0 zero-length status stage */

      usbtrace(TRACE_COMPLETE(privep->epphy), privreq->req.xfrd);

      if (g_ep0outdataend)
        {
          /* The class OUT data stage already ended with DATAEND, so the core
           * completes the status stage itself (vendor HAL switches to
           * HAL_PCD_EP0_STATUSIN and never writes TXPKTRDY again,
           * bf0_hal_pcd.c:663-669 / :1283-1290).  Writing another packet here
           * would put a spurious DATAEND packet on the bus.
           */

          g_ep0outdataend = false;
        }
      else
        {
          priv->hw->index = 0;
          priv->hw->csr0_txcsr = USB_CSR0_TXPKTRDY | USB_CSR0_P_DATAEND;
        }

      sf32lb52_abortrequest(privep, privreq, OK);
    }
  else if (req->len == 0 && (privep->in || privep->epphy == SF32LB52_EPINTRIN))
    {
      usbtrace(TRACE_DEVERROR(SF32LB52_TRACEERR_NULLPACKET), 0);

      /* Non-EP0 zero-length IN packet */

      priv->hw->index = privep->epphy;
      priv->hw->csr0_txcsr = (priv->hw->csr0_txcsr & ~USB_TXCSR_P_WZC_BITS)
                              | USB_TXCSR_TXPKTRDY;
      sf32lb52_abortrequest(privep, privreq, OK);
    }
  else if (privep->in || privep->epphy == SF32LB52_EPINTRIN)
    {
      /* IN request */

      sf32lb52_rqenqueue(privep, privreq);
      usbtrace(TRACE_INREQQUEUED(privep->epphy), privreq->req.len);
      ret = sf32lb52_wrrequest(privep);
    }
  else
    {
      /* OUT request */

      privep->txnullpkt = 0;
      sf32lb52_rqenqueue(privep, privreq);
      usbtrace(TRACE_OUTREQQUEUED(privep->epphy), privreq->req.len);

      /* Only the data (non-control) OUT endpoints use the receive path.
       * EP0 is driven entirely from sf32lb52_ep0setup(): rxpending is a
       * single global flag that EP2 sets, so letting it trigger a read here
       * made EP0 swallow a control packet and the host then reported
       * "device descriptor request failed".
       */

      if (privep->epphy != 0)
        {
          if (priv->rxpending)
            {
              ret = sf32lb52_rdrequest(privep);
              priv->rxpending = 0;
            }
          else
            {
              /* The rxpending flag can also be out of step with the
               * controller: when that happens the packet sits in the FIFO
               * forever, because the core raises no further RX interrupt
               * while RXPKTRDY is still set, and the bulk OUT pipe stops for
               * good.  Ask the hardware instead.
               */

              uint8_t saved = priv->hw->index;

              priv->hw->index = privep->epphy;
              if ((priv->hw->rxcsr & USB_RXCSR_RXPKTRDY) != 0)
                {
                  ret = sf32lb52_rdrequest(privep);
                }

              priv->hw->index = saved;
            }
        }
    }

  leave_critical_section(flags);
  return ret;
}

