670	/****************************************************************************
671	 * Name: sf32lb52_wrrequest
672	 *
673	 * Description:
674	 *   Send from the next queued write request
675	 *
676	 ****************************************************************************/
677	
678	static int sf32lb52_wrrequest(struct sf32lb52_ep_s *privep)
679	{
680	  struct sf32lb52_req_s *privreq;
681	  uint8_t *buf;
682	  int nbytes;
683	  int bytesleft;
684	  int nbyteswritten;
685	  bool last = false;
686	
687	  privreq = sf32lb52_rqpeek(privep);
688	  if (!privreq)
689	    {
690	      usbtrace(TRACE_DEVERROR(SF32LB52_TRACEERR_NULLREQUEST), 0);
691	      return OK;
692	    }
693	
694	  bytesleft = privreq->req.len - privreq->req.xfrd;
695	
696	  usbtrace(TRACE_WRITE(privep->epphy), privreq->req.xfrd);
697	
698	  /* Transmit at most ONE packet per call.  The MUSB controller requires
699	   * the host to drain the FIFO (TXPKTRDY auto-clears -> TX-complete
700	   * interrupt) before the next packet may be written.  Chaining packets
701	   * here overwrites the FIFO and corrupts multi-packet transfers, e.g.
702	   * the 75-byte configuration descriptor on EP0.
703	   */
704	
705	  if (bytesleft > 0 || privep->txnullpkt)
706	    {
707	      privep->txnullpkt = 0;
708	      if (bytesleft > privep->ep.maxpacket)
709	        {
710	          nbytes = privep->ep.maxpacket;
711	        }
712	      else
713	        {
714	          nbytes = bytesleft;
715	          if ((privreq->req.flags & USBDEV_REQFLAGS_NULLPKT) != 0)
716	            {
717	              privep->txnullpkt = (bytesleft == privep->ep.maxpacket);
718	            }
719	        }
720	
721	      buf = privreq->req.buf + privreq->req.xfrd;
722	
723	      /* 末包判定：本包发完即发完整个请求，且不欠 ZLP 时才是末包 */
724	      last = ((privreq->req.xfrd + nbytes) >= privreq->req.len) &&
725	             !privep->txnullpkt;
726	
727	      nbyteswritten = sf32lb52_epwrite(privep->dev, privep->epphy,
728	                                       buf, nbytes, last);
729	      if (nbyteswritten < 0 || nbyteswritten != nbytes)
730	        {
731	          usbtrace(TRACE_DEVERROR(SF32LB52_TRACEERR_EWRITE),
732	                   nbyteswritten);
733	          return ERROR;
734	        }
735	
736	      privreq->req.xfrd += nbytes;
737	    }
738	
739	  /* Transfer is complete only when the whole request fit in this packet
740	   * and no zero-length packet is still owed.  Otherwise the TX-complete
741	   * interrupt calls us again to send the next packet.
742	   */
743	
744	  if (privreq->req.xfrd >= privreq->req.len && !privep->txnullpkt)
745	    {
746	      usbtrace(TRACE_COMPLETE(privep->epphy), privreq->req.xfrd);
747	      privep->txnullpkt = 0;
748	      sf32lb52_reqcomplete(privep, OK);
749	    }
750	
751	  return OK;
752	}
