754	/****************************************************************************
755	 * Name: sf32lb52_rdrequest
756	 *
757	 * Description:
758	 *   Receive to the next queued read request
759	 *
760	 ****************************************************************************/
761	
762	static int sf32lb52_rdrequest(struct sf32lb52_ep_s *privep)
763	{
764	  struct sf32lb52_req_s *privreq;
765	  volatile USBC_X_Typedef *hw = privep->dev->hw;
766	  uint8_t *buf;
767	  int nbytesread;
768	
769	  privreq = sf32lb52_rqpeek(privep);
770	  if (!privreq)
771	    {
772	      usbtrace(TRACE_DEVERROR(SF32LB52_TRACEERR_NULLREQUEST), 0);
773	      return OK;
774	    }
775	
776	  /* RXCOUNT is only valid while RXPKTRDY is set.  The controller keeps the
777	   * FIFO contents and the count after the packet has been read, so reading
778	   * again without a fresh packet re-delivers the previous payload: the
779	   * request then completes twice and the class driver's reassembly state
780	   * (RNDIS current_rx_received/msglen) is corrupted for good.  NAK instead
781	   * and let the RX interrupt pick the request up when data really arrives.
782	   */
783	
784	  if (privep->epphy != 0)
785	    {
786	      hw->index = privep->epphy;
787	      if ((hw->rxcsr & USB_RXCSR_RXPKTRDY) == 0)
788	        {
789	          return OK;
790	        }
791	    }
792	
793	  usbtrace(TRACE_READ(privep->epphy), privreq->req.xfrd);
794	
795	  buf = privreq->req.buf + privreq->req.xfrd;
796	  nbytesread = sf32lb52_epread(privep->dev, privep->epphy,
797	                               buf, privep->ep.maxpacket);
798	  if (nbytesread < 0)
799	    {
800	      usbtrace(TRACE_DEVERROR(SF32LB52_TRACEERR_EPREAD), nbytesread);
801	      return ERROR;
802	    }
803	
804	  privreq->req.xfrd += nbytesread;
805	  if (privreq->req.xfrd >= privreq->req.len ||
806	      nbytesread < privep->ep.maxpacket)
807	    {
808	      usbtrace(TRACE_COMPLETE(privep->epphy), privreq->req.xfrd);
809	      sf32lb52_reqcomplete(privep, OK);
810	    }
811	
812	  return OK;
813	}
