 * Name: sf32lb52_abortrequest
 ****************************************************************************/

static inline void sf32lb52_abortrequest(struct sf32lb52_ep_s *privep,
                                         struct sf32lb52_req_s *privreq,
                                         int16_t result)
{
  usbtrace(TRACE_DEVERROR(SF32LB52_TRACEERR_REQABORTED),
