  privreq->req.callback(&privep->ep, &privreq->req);
}

/****************************************************************************
 * Name: sf32lb52_reqcomplete
 ****************************************************************************/

static void sf32lb52_reqcomplete(struct sf32lb52_ep_s *privep,
                                 int16_t result)
{
  struct sf32lb52_req_s *privreq;
  int stalled = privep->stalled;
  irqstate_t flags;

  flags = enter_critical_section();
  privreq = sf32lb52_rqdequeue(privep);
  leave_critical_section(flags);

  if (privreq)
    {
      if (privep->epphy == 0)
        {
          if (privep->dev->stalled)
            {
              privep->stalled = 1;
            }
        }

      privreq->req.result = result;
      privreq->flink = NULL;
      privreq->req.callback(&privep->ep, &privreq->req);

      privep->stalled = stalled;
    }
}

/****************************************************************************
 * Name: sf32lb52_wrrequest
 *
 * Description:
 *   Send from the next queued write request
 *
 ****************************************************************************/

static int sf32lb52_wrrequest(struct sf32lb52_ep_s *privep)
{
  struct sf32lb52_req_s *privreq;
  uint8_t *buf;
  int nbytes;
  int bytesleft;
  int nbyteswritten;
  bool last = false;

  privreq = sf32lb52_rqpeek(privep);
  if (!privreq)
    {
      usbtrace(TRACE_DEVERROR(SF32LB52_TRACEERR_NULLREQUEST), 0);
      return OK;
    }

  bytesleft = privreq->req.len - privreq->req.xfrd;

  usbtrace(TRACE_WRITE(privep->epphy), privreq->req.xfrd);

  /* Transmit at most ONE packet per call.  The MUSB controller requires
   * the host to drain the FIFO (TXPKTRDY auto-clears -> TX-complete
   * interrupt) before the next packet may be written.  Chaining packets
   * here overwrites the FIFO and corrupts multi-packet transfers, e.g.
   * the 75-byte configuration descriptor on EP0.
   */

  if (bytesleft > 0 || privep->txnullpkt)
    {
      privep->txnullpkt = 0;
      if (bytesleft > privep->ep.maxpacket)
        {
          nbytes = privep->ep.maxpacket;
        }
      else
        {
          nbytes = bytesleft;
          if ((privreq->req.flags & USBDEV_REQFLAGS_NULLPKT) != 0)
            {
              privep->txnullpkt = (bytesleft == privep->ep.maxpacket);
            }
        }

      buf = privreq->req.buf + privreq->req.xfrd;

      /* 末包判定：本包发完即发完整个请求，且不欠 ZLP 时才是末包 */
      last = ((privreq->req.xfrd + nbytes) >= privreq->req.len) &&
             !privep->txnullpkt;

      nbyteswritten = sf32lb52_epwrite(privep->dev, privep->epphy,
                                       buf, nbytes, last);
      if (nbyteswritten < 0 || nbyteswritten != nbytes)
        {
