/****************************************************************************
 * Name: sf32lb52_rdrequest
 *
 * Description:
 *   Receive to the next queued read request
 *
 ****************************************************************************/

static int sf32lb52_rdrequest(struct sf32lb52_ep_s *privep)
{
  struct sf32lb52_req_s *privreq;
  volatile USBC_X_Typedef *hw = privep->dev->hw;
  uint8_t *buf;
  int nbytesread;

  privreq = sf32lb52_rqpeek(privep);
  if (!privreq)
    {
      usbtrace(TRACE_DEVERROR(SF32LB52_TRACEERR_NULLREQUEST), 0);
      return OK;
    }

  /* RXCOUNT is only valid while RXPKTRDY is set.  The controller keeps the
   * FIFO contents and the count after the packet has been read, so reading
   * again without a fresh packet re-delivers the previous payload: the
   * request then completes twice and the class driver's reassembly state
   * (RNDIS current_rx_received/msglen) is corrupted for good.  NAK instead
   * and let the RX interrupt pick the request up when data really arrives.
   */

  if (privep->epphy != 0)
    {
      hw->index = privep->epphy;
      if ((hw->rxcsr & USB_RXCSR_RXPKTRDY) == 0)
        {
          return OK;
        }
    }

  usbtrace(TRACE_READ(privep->epphy), privreq->req.xfrd);

  buf = privreq->req.buf + privreq->req.xfrd;
  nbytesread = sf32lb52_epread(privep->dev, privep->epphy,
                               buf, privep->ep.maxpacket);
  if (nbytesread < 0)
    {
      usbtrace(TRACE_DEVERROR(SF32LB52_TRACEERR_EPREAD), nbytesread);
      return ERROR;
    }

  privreq->req.xfrd += nbytesread;
  if (privreq->req.xfrd >= privreq->req.len ||
      nbytesread < privep->ep.maxpacket)
    {
      usbtrace(TRACE_COMPLETE(privep->epphy), privreq->req.xfrd);
      sf32lb52_reqcomplete(privep, OK);
    }

  return OK;
}

