  if (bytesleft > nbytes)
    {
      bytesleft = nbytes;
    }

  int ret = bytesleft;

  /* Read data from FIFO using 32-bit access when possible */

  if (((uintptr_t)buf & 0x03) == 0)
    {
      uint32_t *buf32 = (uint32_t *)buf;
      while (bytesleft >= 4)
        {
          *buf32++ = hw->fifox[epphy];
